// Rough rendered width in em, used to shrink a line that would not fit its box.
const est = (t) => Array.from(str(t)).reduce((w, ch) => w + (/[\uac00-\ud7a3぀-ヿ一-鿿]/.test(ch) ? 0.95 : ch === ' ' ? 0.28 : /[0-9A-Za-z%]/.test(ch) ? 0.58 : 0.42), 0);

