const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const clone = (v: any) => JSON.parse(JSON.stringify(v));
const enc = (s: string) => new TextEncoder().encode(s);
const dec = (b: any) => new TextDecoder().decode(b);
// Shell quoting: the macOS login shell, or a cmd.exe batch file on Windows (percent doubled, no quotes inside).
const pq = (s: string) => "'" + String(s).replace(/'/g, "'\\''") + "'";
const wq = (s: string) => '"' + String(s).replace(/%/g, "%%").replace(/"/g, "") + '"';
const qa = (s: string) => (IS_WIN ? wq(s) : pq(s));
const r1 = (x: number) => Math.round(x * 10) / 10;

function langOf(context: any): string {
  const l = String(context?.language || "en").toLowerCase().split(/[-_]/)[0];
  return STRINGS[l] ? l : "en";
}
function nameOf(t: any, lang: string): string {
  return (t && (t.name || t.names?.[lang] || t.names?.en || t.id)) || "";
}
function descOf(t: any, lang: string): string {
  return (t && (t.descriptions?.[lang] || t.descriptions?.en)) || "";
}
function merge(base: any, over: any): any {
  if (over === undefined) return base;
  if (Array.isArray(base) || Array.isArray(over)) return over;
  if (base && over && typeof base === "object" && typeof over === "object") {
    const out: any = { ...base };
    for (const k of Object.keys(over)) out[k] = merge(base[k], over[k]);
    return out;
  }
  return over;
}
// A failed script answers with a JSON report; its own words are the message, not the whole report.
function scriptError(output: any): string {
  const text = String(output || "run_script failed");
  try {
    const j = JSON.parse(text);
    if (j && typeof j.error === "string") {
      const more = Array.isArray(j.colorOps?.failures) ? j.colorOps.failures.map((f: any) => String(f).replace(/^Error:\s*/, "")) : [];
      return [j.error, ...more].join(" ").slice(0, 600);
    }
  } catch (e) {}
  return text.slice(0, 1200);
}
function extractJson(text: string, S: any): any {
  const s = String(text || "");
  const fence = s.match(/```(?:json)?\s*([\s\S]*?)```/);
  const body = fence ? fence[1] : s;
  const a = body.indexOf("{");
  const b = body.lastIndexOf("}");
  if (a < 0 || b <= a) throw new Error(S.noJson);
  return JSON.parse(body.slice(a, b + 1));
}

// ---- Media files and durable host-owned metadata storage ----
function hostFs(): any {
  try {
    const fs = hostSdk.files;
    const need = ["readFile", "writeFile", "homedir", "join", "exists", "mkdir", "readdir", "rm"];
    return fs && need.every((k) => typeof fs[k] === "function") ? fs : null;
  } catch (e) {
    return null;
  }
}

// Project switches mount a new store, but its metadata shares the same backend.
const metadataWrites = new WeakMap<object, Map<string, Promise<void>>>();
function metadataQueue(backend: object) {
  let queue = metadataWrites.get(backend);
  if (!queue) { queue = new Map(); metadataWrites.set(backend, queue); }
  return queue;
}
function writeMetadata(backend: object, key: string, write: () => Promise<void>) {
  const queue = metadataQueue(backend);
  const pending = (queue.get(key) || Promise.resolve()).catch(() => {}).then(write);
  queue.set(key, pending);
  return pending;
}
function makeStore() {
  const fs = hostFs();
  const storeSdk = hostSdk;
  if (fs) {
    const root = fs.join(fs.homedir(), ".selects", "plugin-data", APP_ID);
    const dir = (n: string) => fs.join(root, n);
    const ensure = async (p: string) => {
      if (!(await fs.exists(p))) (await fs.mkdir(p, { recursive: true }));
    };
    return {
      fs,
      root,
      media: dir("media"),
      bin: dir("bin"),
      refs: dir("references"),
      join: (...p: string[]) => fs.join(...p),
      ensure,
      exists: async (p: string) => {
        try {
          return (await fs.exists(p)) && (typeof fs.stat !== "function" || (await fs.stat(p)).size > 0);
        } catch (e) {
          return false;
        }
      },
      async list(kind: string) {
        await metadataQueue(fs).get(dir(kind));
        const d = dir(kind);
        if (!(await fs.exists(d))) return [];
        const out: any[] = [];
        for (const n of (await fs.readdir(d))) {
          if (!/\.json$/.test(n)) continue;
          try {
            out.push(JSON.parse(dec(await fs.readFile(fs.join(d, n)))));
          } catch (e) {}
        }
        return out;
      },
      async put(kind: string, id: string, v: any) {
        const snapshot = enc(JSON.stringify(v));
        await writeMetadata(fs, dir(kind), async () => {
          const d = dir(kind);
          await ensure(d);
          await fs.writeFile(fs.join(d, id + ".json"), snapshot);
        });
      },
      async del(kind: string, id: string) {
        await writeMetadata(fs, dir(kind), async () => {
          const p = fs.join(dir(kind), id + ".json");
          if (await fs.exists(p)) await fs.rm(p);
        });
      },
    };
  }
  const key = (kind: string) => `${APP_ID}:${kind}`;
  const storage = () => {
    if (!storeSdk.storage?.getItem || !storeSdk.storage?.setItem)
      throw new Error("Update Selects to use persistent plugin storage, then reopen this panel.");
    return storeSdk.storage;
  };
  const read = async (kind: string) => JSON.parse(await storage().getItem(key(kind)) || "{}") || {};
  const change = (kind: string, edit: (all: any) => void) => {
    const backend = storage();
    return writeMetadata(backend, key(kind), async () => {
      const all = JSON.parse(await backend.getItem(key(kind)) || "{}") || {};
      edit(all);
      await backend.setItem(key(kind), JSON.stringify(all));
    });
  };
  return {
    fs: null,
    root: null,
    media: null,
    bin: null,
    refs: null,
    join: (...p: string[]) => p.join(IS_WIN ? "\\" : "/"),
    ensure: (_: string) => {},
    exists: (_: string) => false,
    async list(kind: string) {
      await metadataQueue(storage()).get(key(kind));
      return Object.values(await read(kind));
    },
    async put(kind: string, id: string, v: any) {
      const snapshot = JSON.parse(JSON.stringify(v));
      await change(kind, all => { all[id] = snapshot; });
    },
    async del(kind: string, id: string) {
      await change(kind, all => { delete all[id]; });
    },
  };
}

function useWidth(ref: any, fallback: number): number {
  const [w, setW] = React.useState(fallback);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const read = () => setW(el.clientWidth || fallback);
    read();
    const ro = new ResizeObserver(read);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  return w;
}

// Pictures travel inside each short's run_script, which Selects caps at 262,144 bytes, so a background is
// kept under about 110 KB and each other picture under about 60 KB, as base64 WebP (PNG for transparency).
const IMAGE_BUDGET = { background: 110000, picture: 60000 };
const SCRIPT_LIMIT = 238000;

async function bitmapToDataUrl(bmp: ImageBitmap, kind: "background" | "picture", W: number, H: number): Promise<string> {
  const budget = IMAGE_BUDGET[kind];
  const scales = [1, 0.8, 0.66, 0.5, 0.4];
  const quals = [0.85, 0.75, 0.62, 0.5];
  let last = "";
  for (const sc of scales) {
    let w: number, h: number, sx = 0, sy = 0, sw = bmp.width, sh = bmp.height;
    if (kind === "background") {
      w = Math.round(W * sc);
      h = Math.round(H * sc);
      const r = Math.max(w / bmp.width, h / bmp.height);
      sw = w / r;
      sh = h / r;
      sx = (bmp.width - sw) / 2;
      sy = (bmp.height - sh) / 2;
    } else {
      const r = Math.min(1, (900 * sc) / bmp.width);
      w = Math.max(1, Math.round(bmp.width * r));
      h = Math.max(1, Math.round(bmp.height * r));
    }
    const c = document.createElement("canvas");
    c.width = w;
    c.height = h;
    c.getContext("2d")!.drawImage(bmp, sx, sy, sw, sh, 0, 0, w, h);
    for (const q of quals) {
      let url = c.toDataURL("image/webp", q);
      if (!url.startsWith("data:image/webp")) url = kind === "picture" ? c.toDataURL("image/png") : c.toDataURL("image/jpeg", q);
      last = url;
      if (url.length <= budget) return url;
    }
  }
  if (last.length <= budget * 1.3) return last;
  throw new Error("too large");
}

async function fileToDataUrl(fs: any, path: string, kind: "background" | "picture", W: number, H: number): Promise<{ url: string; w: number; h: number }> {
  const bmp = await createImageBitmap(new Blob([await fs.readFile(path)]));
  return { url: await bitmapToDataUrl(bmp, kind, W, H), w: bmp.width, h: bmp.height };
}

// ---- Reference analysis: measure a channel's layout from its shorts, then let the AI read the style ----
// Every reference short contributes a strip of small frames (for motion) and a few full-size frames (for
// pictures and colours). Across the strip, the area that keeps moving is the video box. Across the
// references, what stays the same outside it is the background (and its logos), and what is still within a
// short but differs between shorts is text written per short: the headlines.

type Frame = { w: number; h: number; d: Uint8ClampedArray };

async function loadFrame(fs: any, path: string, w?: number, h?: number): Promise<Frame> {
  const bmp = await createImageBitmap(new Blob([await fs.readFile(path)]));
  const W = w || bmp.width;
  const H = h || bmp.height;
  const c = document.createElement("canvas");
  c.width = W;
  c.height = H;
  const g = c.getContext("2d", { willReadFrequently: true } as any)! as CanvasRenderingContext2D;
  g.drawImage(bmp, 0, 0, W, H);
  return { w: W, h: H, d: g.getImageData(0, 0, W, H).data };
}

const hex2 = (n: number) => Math.max(0, Math.min(255, Math.round(n))).toString(16).padStart(2, "0").toUpperCase();
const toHex = (r: number, g: number, b: number) => "#" + hex2(r) + hex2(g) + hex2(b);
function median(a: number[]): number {
  if (!a.length) return 0;
  const s = a.slice().sort((x, y) => x - y);
  return s[s.length >> 1];
}

// Longest run of indexes whose value passes `ok`, allowing short gaps.
function longestRun(vals: number[], ok: (v: number) => boolean, gap: number): [number, number] | null {
  let best: [number, number] | null = null;
  let start = -1;
  let last = -1;
  for (let i = 0; i <= vals.length; i++) {
    const pass = i < vals.length && ok(vals[i]);
    if (pass) {
      if (start < 0) start = i;
      last = i;
    } else if (start >= 0 && i - last > gap) {
      if (!best || last - start > best[1] - best[0]) best = [start, last];
      start = -1;
    }
  }
  if (start >= 0 && (!best || last - start > best[1] - best[0])) best = [start, last];
  return best;
}

// Connected boxes of a mask, after joining nearby pixels (text letters into lines).
function boxesOf(mask: Uint8Array, w: number, h: number, joinX: number, joinY: number, minArea: number) {
  const grown = new Uint8Array(w * h);
  for (let y = 0; y < h; y++)
    for (let x = 0; x < w; x++) {
      if (!mask[y * w + x]) continue;
      for (let yy = Math.max(0, y - joinY); yy <= Math.min(h - 1, y + joinY); yy++)
        for (let xx = Math.max(0, x - joinX); xx <= Math.min(w - 1, x + joinX); xx++) grown[yy * w + xx] = 1;
    }
  const seen = new Uint8Array(w * h);
  const out: any[] = [];
  const stack: number[] = [];
  for (let i = 0; i < w * h; i++) {
    if (!grown[i] || seen[i]) continue;
    let x0 = w, y0 = h, x1 = 0, y1 = 0, n = 0, hits = 0;
    stack.push(i);
    seen[i] = 1;
    while (stack.length) {
      const p = stack.pop()!;
      const x = p % w;
      const y = (p - x) / w;
      n++;
      if (mask[p]) hits++;
      if (x < x0) x0 = x;
      if (x > x1) x1 = x;
      if (y < y0) y0 = y;
      if (y > y1) y1 = y;
      const nb = [p - 1, p + 1, p - w, p + w];
      for (const q of nb) {
        if (q < 0 || q >= w * h || seen[q] || !grown[q]) continue;
        if ((q === p - 1 && x === 0) || (q === p + 1 && x === w - 1)) continue;
        seen[q] = 1;
        stack.push(q);
      }
    }
    // Shrink back by the join distance so the box hugs the marked pixels.
    const b = { x: Math.min(x1, x0 + joinX), y: Math.min(y1, y0 + joinY), w: 0, h: 0, hits };
    b.w = Math.max(1, x1 - joinX - b.x + 1);
    b.h = Math.max(1, y1 - joinY - b.y + 1);
    if (hits >= minArea) out.push(b);
  }
  return out;
}

// strips[r][k]: small frames of reference r. Returns boxes in small-frame pixels.
function measureLayout(strips: Frame[][]) {
  const R = strips.length;
  const w = strips[0][0].w;
  const h = strips[0][0].h;
  const N = w * h;
  const moving = new Float32Array(N);
  const means: Float32Array[] = [];
  const stills = new Float32Array(N);
  for (const frames of strips) {
    const K = frames.length;
    const sum = new Float32Array(N);
    const sq = new Float32Array(N);
    const mean = new Float32Array(N * 3);
    for (const f of frames) {
      for (let i = 0; i < N; i++) {
        const r = f.d[i * 4], g = f.d[i * 4 + 1], b = f.d[i * 4 + 2];
        const y = 0.299 * r + 0.587 * g + 0.114 * b;
        sum[i] += y;
        sq[i] += y * y;
        mean[i * 3] += r / K;
        mean[i * 3 + 1] += g / K;
        mean[i * 3 + 2] += b / K;
      }
    }
    for (let i = 0; i < N; i++) {
      const m = sum[i] / K;
      const sd = Math.sqrt(Math.max(0, sq[i] / K - m * m));
      if (sd > 14) moving[i] += 1 / R;
      if (sd < 6) stills[i] += 1 / R;
    }
    means.push(mean);
  }
  // How much each pixel's average colour differs between references.
  const across = new Float32Array(N);
  for (let i = 0; i < N; i++) {
    let worst = 0;
    for (let c = 0; c < 3; c++) {
      let s = 0, s2 = 0;
      for (const m of means) {
        s += m[i * 3 + c];
        s2 += m[i * 3 + c] * m[i * 3 + c];
      }
      const mu = s / R;
      worst = Math.max(worst, Math.sqrt(Math.max(0, s2 / R - mu * mu)));
    }
    across[i] = worst;
  }
  // The video box: rows, then columns, where most pixels keep moving in most references.
  const rowFrac: number[] = [];
  for (let y = 0; y < h; y++) {
    let n = 0;
    for (let x = 0; x < w; x++) if (moving[y * w + x] >= 0.5) n++;
    rowFrac.push(n / w);
  }
  // A short gap ends a run, so a caption band right under the video stays a separate band.
  let rows = longestRun(rowFrac, (v) => v > 0.3, 1);
  if (!rows || rows[1] - rows[0] < h * 0.1) rows = [0, h - 1];
  // Other moving bands (captions on a band of their own, for example), in small-frame rows.
  const bands: number[][] = [];
  {
    let st = -1;
    for (let y = 0; y <= h; y++) {
      const on = y < h && rowFrac[y] > 0.3 && (y < rows[0] || y > rows[1]);
      if (on && st < 0) st = y;
      if (!on && st >= 0) {
        if (y - st >= 3) bands.push([st, y - 1]);
        st = -1;
      }
    }
  }
  const colFrac: number[] = [];
  for (let x = 0; x < w; x++) {
    let n = 0;
    for (let y = rows[0]; y <= rows[1]; y++) if (moving[y * w + x] >= 0.5) n++;
    colFrac.push(n / (rows[1] - rows[0] + 1));
  }
  let cols = longestRun(colFrac, (v) => v > 0.3, Math.round(w * 0.02));
  if (!cols || cols[1] - cols[0] < w * 0.2) cols = [0, w - 1];
  // The window can be larger than the moving part (a still studio wall around the speaker). The template's
  // own background looks the same in every short; the window's content, still or not, differs from short
  // to short. Grow the box outwards while whole rows and columns are window content.
  // Window content: moving, or different between shorts even where it is still (the template's own
  // background and bars are identical in every short).
  const win = (i: number) => moving[i] >= 0.5 || across[i] > 8;
  const rowWin = (y: number, a: number, b: number) => {
    let n = 0;
    for (let x = a; x <= b; x++) if (win(y * w + x)) n++;
    return n / (b - a + 1);
  };
  const colWin = (x: number, a: number, b: number) => {
    let n = 0;
    for (let y = a; y <= b; y++) if (win(y * w + x)) n++;
    return n / (b - a + 1);
  };
  for (let pass = 0; pass < 2; pass++) {
    while (cols[0] > 0 && colWin(cols[0] - 1, rows[0], rows[1]) > 0.7) cols[0]--;
    while (cols[1] < w - 1 && colWin(cols[1] + 1, rows[0], rows[1]) > 0.7) cols[1]++;
    while (rows[0] > 0 && rowWin(rows[0] - 1, cols[0], cols[1]) > 0.7) rows[0]--;
    while (rows[1] < h - 1 && rowWin(rows[1] + 1, cols[0], cols[1]) > 0.7) rows[1]++;
  }
  const snap = (a: number, b: number, n: number): [number, number] => [a <= n * 0.025 ? 0 : a, b >= n * 0.975 ? n - 1 : b];
  [rows[0], rows[1]] = snap(rows[0], rows[1], h);
  [cols[0], cols[1]] = snap(cols[0], cols[1], w);
  const video = { x: cols[0], y: rows[0], w: cols[1] - cols[0] + 1, h: rows[1] - rows[0] + 1 };
  const fullScreen = video.w * video.h > N * 0.85;
  const inVideo = (x: number, y: number) => x >= video.x && x < video.x + video.w && y >= video.y && y < video.y + video.h;
  // The background colour: what stays put and looks the same in every reference, outside the video box.
  const bgPix: number[][] = [[], [], []];
  for (let i = 0; i < N; i += 2) {
    const x = i % w, y = (i - x) / w;
    if (inVideo(x, y) || across[i] > 10 || moving[i] > 0.2) continue;
    for (let c = 0; c < 3; c++) bgPix[c].push(means[0][i * 3 + c]);
  }
  const bg = bgPix[0].length ? [median(bgPix[0]), median(bgPix[1]), median(bgPix[2])] : [0, 0, 0];
  let spread = 0;
  for (let k = 0; k < bgPix[0].length; k++) spread += Math.abs(bgPix[0][k] - bg[0]) + Math.abs(bgPix[1][k] - bg[1]) + Math.abs(bgPix[2][k] - bg[2]);
  const uniform = bgPix[0].length > 0 && spread / bgPix[0].length < 18;
  // Per-short text: still within each short, different between shorts. Over the video only line-shaped
  // marks count, so a still studio picture is not taken for text.
  const textMask = new Uint8Array(N);
  for (let i = 0; i < N; i++) if (stills[i] >= 0.6 && moving[i] < 0.3 && across[i] > 28) textMask[i] = 1;
  const minArea = Math.max(12, Math.round(N * 0.0006));
  let texts = boxesOf(textMask, w, h, Math.max(2, Math.round(w * 0.03)), Math.max(1, Math.round(h * 0.004)), minArea);
  texts = texts.filter((b: any) => {
    const cx = b.x + b.w / 2, cy = b.y + b.h / 2;
    if (!inVideo(cx, cy)) return true;
    return b.w / b.h > 2.5 && b.h < h * 0.12;
  });
  // Marks that are the same in every short (logos, fixed labels) over the video: kept as picture layers.
  const fixedMask = new Uint8Array(N);
  for (let i = 0; i < N; i++) {
    const x = i % w, y = (i - x) / w;
    if (!inVideo(x, y) || moving[i] > 0.15 || across[i] > 8) continue;
    const m = means[0];
    if (Math.abs(m[i * 3] - bg[0]) + Math.abs(m[i * 3 + 1] - bg[1]) + Math.abs(m[i * 3 + 2] - bg[2]) > 60 || fullScreen) fixedMask[i] = stills[i] >= 0.8 ? 1 : 0;
  }
  const fixed = boxesOf(fixedMask, w, h, 2, 2, minArea).filter((b: any) => b.w < w * 0.6 && b.h < h * 0.2);
  texts.sort((a: any, b: any) => a.y - b.y);
  return { w, h, video, fullScreen, bg: toHex(bg[0], bg[1], bg[2]), uniform, texts, fixed, bands };
}

// The background picture: the per-pixel median of the full-size frames, so anything that differs between
// shorts drops out. Inside the areas where text is written per short (headlines, a caption band) the
// letters overlap too much for a median, so there each pixel takes the short whose value is closest to the
// area's surrounding colour: one short without a letter there is enough.
function backgroundImage(fulls: Frame[], bgHex: string, video: any, clear: any[] = []): HTMLCanvasElement {
  const W = fulls[0].w, H = fulls[0].h, N = W * H;
  const zone = new Int16Array(N).fill(-1);
  const backs: number[][] = [];
  const spans: number[][] = [];
  const holes = new Uint8Array(N);
  clear.forEach((b, z) => {
    const x0 = Math.max(0, Math.round(b.x - 10)), y0 = Math.max(0, Math.round(b.y - 10));
    const x1 = Math.min(W - 1, Math.round(b.x + b.w + 10)), y1 = Math.min(H - 1, Math.round(b.y + b.h + 10));
    const e: number[][] = [[], [], []];
    for (const f of fulls) {
      for (let x = x0; x <= x1; x += 3) for (const y of [y0, y1]) for (let c = 0; c < 3; c++) e[c].push(f.d[(y * W + x) * 4 + c]);
      for (let y = y0; y <= y1; y += 3) for (const x of [x0, x1]) for (let c = 0; c < 3; c++) e[c].push(f.d[(y * W + x) * 4 + c]);
    }
    backs.push([median(e[0]), median(e[1]), median(e[2])]);
    spans.push([x0, y0, x1, y1]);
    for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) zone[y * W + x] = z;
  });
  const bg = [parseInt(bgHex.slice(1, 3), 16), parseInt(bgHex.slice(3, 5), 16), parseInt(bgHex.slice(5, 7), 16)];
  const c = document.createElement("canvas");
  c.width = W;
  c.height = H;
  const g = c.getContext("2d")!;
  const img = g.createImageData(W, H);
  const vals = new Array(fulls.length);
  for (let i = 0; i < N; i++) {
    const x = i % W, y = (i - x) / W;
    const p = i * 4;
    if (x >= video.x && x < video.x + video.w && y >= video.y && y < video.y + video.h) {
      img.data[p] = bg[0];
      img.data[p + 1] = bg[1];
      img.data[p + 2] = bg[2];
      img.data[p + 3] = 255;
      continue;
    }
    if (zone[i] >= 0) {
      const t = backs[zone[i]];
      let best = fulls[0].d, bd = Infinity;
      for (const f of fulls) {
        const d = Math.abs(f.d[p] - t[0]) + Math.abs(f.d[p + 1] - t[1]) + Math.abs(f.d[p + 2] - t[2]);
        if (d < bd) {
          bd = d;
          best = f.d;
        }
      }
      img.data[p] = best[p];
      img.data[p + 1] = best[p + 1];
      img.data[p + 2] = best[p + 2];
      if (bd > 45) holes[i] = 1;
    } else if (fulls.length === 2) {
      const a = fulls[0].d, b = fulls[1].d;
      const da = Math.abs(a[p] - bg[0]) + Math.abs(a[p + 1] - bg[1]) + Math.abs(a[p + 2] - bg[2]);
      const db = Math.abs(b[p] - bg[0]) + Math.abs(b[p + 1] - bg[1]) + Math.abs(b[p + 2] - bg[2]);
      const s = da <= db ? a : b;
      img.data[p] = s[p];
      img.data[p + 1] = s[p + 1];
      img.data[p + 2] = s[p + 2];
    } else {
      for (let ch = 0; ch < 3; ch++) {
        for (let k = 0; k < fulls.length; k++) vals[k] = fulls[k].d[p + ch];
        img.data[p + ch] = median(vals);
      }
    }
    img.data[p + 3] = 255;
  }
  // Where every short had text (a box behind a long headline), blend the rows just above and below.
  for (const [x0, y0, x1, y1] of spans) {
    const ya = Math.max(0, y0 - 2), yb = Math.min(H - 1, y1 + 2);
    for (let x = x0; x <= x1; x++)
      for (let y = y0; y <= y1; y++) {
        const i = y * W + x;
        if (!holes[i]) continue;
        const t = (y - ya) / Math.max(1, yb - ya);
        for (let c = 0; c < 3; c++) img.data[i * 4 + c] = Math.round(img.data[(ya * W + x) * 4 + c] * (1 - t) + img.data[(yb * W + x) * 4 + c] * t);
      }
  }
  g.putImageData(img, 0, 0);
  return c;
}

// The text lines inside one box of one full-size frame: for each line its rows, colour and letter height,
// and the colour of a solid box behind the text when there is one.
function textLook(f: Frame, b: any) {
  const x0 = Math.max(0, Math.round(b.x)), y0 = Math.max(0, Math.round(b.y));
  const x1 = Math.min(f.w - 1, Math.round(b.x + b.w)), y1 = Math.min(f.h - 1, Math.round(b.y + b.h));
  const at = (x: number, y: number) => {
    const p = (y * f.w + x) * 4;
    return [f.d[p], f.d[p + 1], f.d[p + 2]];
  };
  const dist = (a: number[], c: number[]) => Math.abs(a[0] - c[0]) + Math.abs(a[1] - c[1]) + Math.abs(a[2] - c[2]);
  const edge: number[][] = [[], [], []];
  for (let x = x0; x <= x1; x += 2) for (const y of [y0, y1]) at(x, y).forEach((v, c) => edge[c].push(v));
  for (let y = y0; y <= y1; y += 2) for (const x of [x0, x1]) at(x, y).forEach((v, c) => edge[c].push(v));
  const back = [median(edge[0]), median(edge[1]), median(edge[2])];
  // The most common colour inside: a box behind the text when it covers much of the area and differs from
  // the surroundings.
  const hist = new Map<number, number[]>();
  let total = 0;
  for (let y = y0; y <= y1; y += 2)
    for (let x = x0; x <= x1; x += 2) {
      const v = at(x, y);
      const k = ((v[0] >> 4) << 8) | ((v[1] >> 4) << 4) | (v[2] >> 4);
      const e = hist.get(k) || [0, 0, 0, 0];
      e[0]++;
      e[1] += v[0];
      e[2] += v[1];
      e[3] += v[2];
      hist.set(k, e);
      total++;
    }
  let top: number[] = [0, 0, 0, 0];
  hist.forEach((e) => {
    if (e[0] > top[0]) top = e;
  });
  const dom = [top[1] / top[0], top[2] / top[0], top[3] / top[0]];
  // A box behind the text fills the whole marked area up to its edges; letters alone do not. Find where
  // anything differs from the surroundings, then check that its four inner edges are the common colour.
  let ex0 = x1, ex1 = x0, ey0 = y1, ey1 = y0;
  for (let y = y0; y <= y1; y += 2)
    for (let x = x0; x <= x1; x += 2)
      if (dist(at(x, y), back) > 120) {
        if (x < ex0) ex0 = x;
        if (x > ex1) ex1 = x;
        if (y < ey0) ey0 = y;
        if (y > ey1) ey1 = y;
      }
  let boxed = false;
  if (ex1 - ex0 > 20 && ey1 - ey0 > 10 && dist(dom, back) > 90) {
    let n = 0, hit = 0;
    const probe = (x: number, y: number) => {
      n++;
      if (dist(at(x, y), dom) < 60) hit++;
    };
    for (let x = ex0 + 3; x <= ex1 - 3; x += 3) {
      probe(x, ey0 + 3);
      probe(x, ey1 - 3);
    }
    for (let y = ey0 + 3; y <= ey1 - 3; y += 3) {
      probe(ex0 + 3, y);
      probe(ex1 - 3, y);
    }
    boxed = n > 0 && hit / n > 0.6;
  }
  const ref = boxed ? dom : back;
  const rowsInk: number[] = [];
  const inkAt: number[][][] = [];
  for (let y = y0; y <= y1; y++) {
    let n = 0;
    const px: number[][] = [];
    for (let x = x0; x <= x1; x++) {
      const v = at(x, y);
      if (dist(v, ref) > 120 && (!boxed || dist(v, back) > 60)) {
        n++;
        if (x % 2 === 0) px.push(v);
      }
    }
    rowsInk.push(n);
    inkAt.push(px);
  }
  const peak = Math.max(1, ...rowsInk);
  const lines: any[] = [];
  let start = -1;
  for (let i = 0; i <= rowsInk.length; i++) {
    const on = i < rowsInk.length && rowsInk[i] > peak * 0.08;
    if (on && start < 0) start = i;
    if (!on && start >= 0) {
      if (i - start > 3) {
        // The letters' own colour: the half of the marked pixels furthest from the background, so
        // anti-aliased edges and background texture do not pull it towards the background.
        let px = inkAt.slice(start, i).flat();
        if (px.length > 8) {
          const ds = px.map((v) => dist(v, ref));
          const cut = median(ds);
          px = px.filter((_, k) => ds[k] >= cut);
        }
        const col = px.length ? toHex(median(px.map((v) => v[0])), median(px.map((v) => v[1])), median(px.map((v) => v[2]))) : "#FFFFFF";
        lines.push({ y0: y0 + start, y1: y0 + i - 1, color: col, inkHeight: i - start });
      }
      start = -1;
    }
  }
  return { back: toHex(back[0], back[1], back[2]), box: boxed ? toHex(dom[0], dom[1], dom[2]) : null, lines };
}

// Split each measured box into text lines (a two-line headline in two colours becomes two layers), using
// the full-size frame of every reference: line positions are the median over references.
function textLines(fulls: Frame[], boxes: any[]) {
  const out: any[] = [];
  for (const b of boxes) {
    const looks = fulls.map((f) => textLook(f, b));
    const n = median(looks.map((l) => l.lines.length));
    if (!n) continue;
    const usable = looks.filter((l) => l.lines.length === n);
    for (let k = 0; k < n; k++) {
      const ls = usable.map((l) => l.lines[k]);
      const y0 = median(ls.map((l) => l.y0));
      const y1 = median(ls.map((l) => l.y1));
      const ink = median(ls.map((l) => l.inkHeight));
      const pad = Math.round(ink * 0.35);
      const colors = ls.map((l) => l.color);
      const color = colors.sort((a, c) => colors.filter((x) => x === c).length - colors.filter((x) => x === a).length)[0];
      const boxes2 = usable.map((l) => l.box).filter(Boolean);
      out.push({ x: b.x, y: y0 - pad, w: b.w, h: y1 - y0 + 1 + pad * 2, color, inkHeight: ink, box: boxes2.length > usable.length / 2 ? boxes2[0] : null });
    }
  }
  return out;
}

// A sheet of frames for the AI, with the measured boxes drawn and labelled.
function sheet(frames: Frame[], boxes: any[], cols: number, cellW: number): string {
  const f0 = frames[0];
  const cellH = Math.round((cellW * f0.h) / f0.w);
  const rows = Math.ceil(frames.length / cols);
  const c = document.createElement("canvas");
  c.width = cols * cellW + (cols - 1) * 8;
  c.height = rows * cellH + (rows - 1) * 8;
  const g = c.getContext("2d")!;
  g.fillStyle = "#FFFFFF";
  g.fillRect(0, 0, c.width, c.height);
  frames.forEach((f, i) => {
    const ox = (i % cols) * (cellW + 8);
    const oy = Math.floor(i / cols) * (cellH + 8);
    const t = document.createElement("canvas");
    t.width = f.w;
    t.height = f.h;
    t.getContext("2d")!.putImageData(new ImageData(new Uint8ClampedArray(f.d), f.w, f.h), 0, 0);
    g.drawImage(t, ox, oy, cellW, cellH);
    const s = cellW / f.w;
    g.lineWidth = 2;
    g.font = "bold 14px sans-serif";
    for (const b of boxes) {
      g.strokeStyle = b.label === "V" ? "#00E5FF" : "#FF2D55";
      g.strokeRect(ox + b.x * s, oy + b.y * s, b.w * s, b.h * s);
      g.fillStyle = g.strokeStyle;
      g.fillText(b.label, ox + b.x * s + 3, oy + b.y * s + 15);
    }
    g.fillStyle = "#000000";
    g.fillRect(ox, oy, 26, 18);
    g.fillStyle = "#FFFFFF";
    g.fillText(String(i + 1), ox + 6, oy + 14);
  });
  let url = c.toDataURL("image/jpeg", 0.82);
  if (url.length > 1400000) url = c.toDataURL("image/jpeg", 0.6);
  return url;
}

const LANG_NAMES: any = { en: "English", ko: "Korean", de: "German", es: "Spanish", fr: "French", it: "Italian", ja: "Japanese", pt: "Portuguese", tr: "Turkish", zh: "Chinese" };

function stylePrompt(m: any, refs: any[]) {
  return [
    "Answer from the pictures and this text only. Do not use any tools, open files or browse.",
    "These pictures come from vertical short videos published by one channel, all made with the same template.",
    "Picture 1 shows the middle frame of each short (numbered). Picture 2 shows the template's background without the video, made from all shorts.",
    `Measured on a ${m.W}x${m.H} canvas: the cyan box V is where the video plays. Red boxes T1, T2, ... are areas whose text changes from short to short. Measured text colours and letter heights per box: ${JSON.stringify(m.measured)}.`,
    "For each red box say what it is (give its label, T1, T2 and so on, as \"label\"): headline1 (the main headline written for each short), headline2 (a second headline line or a subject line), caption (the spoken words, changing within a short), or ignore (anything else). If one box holds two headline lines in different colours, give it as headline1 and give headline2 a separate box you split from it.",
    "Describe each headline's look: alignment, font weight (100-900), italic, text colour, a solid box behind the text and its colour, an outline and its colour, a shadow, and the font size in canvas pixels.",
    "Say whether the shorts have spoken captions, where their centre line sits (y in canvas pixels), their style (box, outline, shadow or plain), colours and size.",
    "If the cyan box is clearly wrong, give the corrected video box. Read the two headlines of every short as they appear.",
    `Answer with JSON only: {"video": {"x": 0, "y": 0, "w": 0, "h": 0} or null, "texts": [{"label": "T1", "role": "headline1|headline2|caption|ignore", "x": 0, "y": 0, "w": 0, "h": 0, "align": "left|center|right", "weight": 800, "italic": false, "color": "#RRGGBB", "size": 80, "textBox": {"on": false, "color": "#RRGGBB"}, "outline": {"on": false, "color": "#000000", "width": 8}, "shadow": false}], "captions": {"on": true, "y": 1400, "style": "box|outline|shadow|plain", "color": "#FFFFFF", "boxColor": "#000000A6", "size": 60, "weight": 700}, "headlines": [{"short": 1, "headline1": "", "headline2": ""}], "description": "one sentence about the look"}`,
    `Short titles in picture order: ${refs.map((r, i) => `${i + 1}. ${r.title}`).join(" | ")}`,
  ].join("\n\n");
}

function learnPrompt(refs: any[], others: any[], headlines: any[], lang: string, durations: number[]) {
  const fmt = (r: any) => `- ${r.title}${r.views != null ? ` (${r.views.toLocaleString("en-US")} views)` : ""}${r.duration ? `, ${Math.round(r.duration)} s` : ""}`;
  return [
    "Answer from this text only. Do not use any tools, open files or browse.",
    "A channel cuts short clips out of its long videos. Below are its shorts used as references (most viewed first), the headlines written on them, and, when known, shorts from the same channel that did less well.",
    "Work out what kind of moment this channel picks for shorts that do well, what does poorly, how long the shorts are, how many it makes per long video if you can tell, and how it writes headlines. These become the rules another editor follows to cut new shorts from this channel's long videos.",
    `Write every rule text in ${LANG_NAMES[lang] || "English"}. Be concrete about topics, hooks and structure; do not invent numbers you cannot see.`,
    `Reference shorts:\n${refs.map(fmt).join("\n")}`,
    `Headlines read from the references: ${JSON.stringify(headlines)}`,
    others.length ? `Shorts that did less well:\n${others.map(fmt).join("\n")}` : "",
    durations.length ? `Reference lengths in seconds: ${durations.map((d) => Math.round(d)).join(", ")}.` : "",
    `Answer with JSON only: {"role": "who the editor is (one sentence)", "format": "what the long source videos are like", "good": "moments that do well", "bad": "moments that do poorly", "lengthGuide": "length range", "countGuide": "how many shorts per long video", "rules": "cutting rules", "headline": "how to write headline1 and headline2, with typical length", "name": "a short name for this template (2-4 words)"}`,
  ]
    .filter(Boolean)
    .join("\n\n");
}

// Group references that share a template: where both are still, they look the same. Shorts whose picture
// is nearly all video (full-screen templates) group together. Returns groups of indexes, largest first.
function groupByLook(strips: Frame[][]): number[][] {
  const R = strips.length;
  const w = strips[0][0].w, h = strips[0][0].h, N = w * h;
  const means: Float32Array[] = [];
  const stills: Uint8Array[] = [];
  const stillShare: number[] = [];
  for (const frames of strips) {
    const K = frames.length;
    const sum = new Float32Array(N), sq = new Float32Array(N);
    for (const f of frames)
      for (let i = 0; i < N; i++) {
        const y = 0.299 * f.d[i * 4] + 0.587 * f.d[i * 4 + 1] + 0.114 * f.d[i * 4 + 2];
        sum[i] += y;
        sq[i] += y * y;
      }
    const m = new Float32Array(N), st = new Uint8Array(N);
    let n = 0;
    for (let i = 0; i < N; i++) {
      m[i] = sum[i] / K;
      if (Math.sqrt(Math.max(0, sq[i] / K - m[i] * m[i])) < 6) {
        st[i] = 1;
        n++;
      }
    }
    means.push(m);
    stills.push(st);
    stillShare.push(n / N);
  }
  const far = (a: number, b: number) => {
    const fa = stillShare[a] < 0.15, fb = stillShare[b] < 0.15;
    if (fa || fb) return fa && fb ? 0 : 255;
    let s = 0, n = 0;
    for (let i = 0; i < N; i += 2)
      if (stills[a][i] && stills[b][i]) {
        s += Math.abs(means[a][i] - means[b][i]);
        n++;
      }
    return n < N * 0.05 ? 255 : s / n;
  };
  const near: number[][] = [];
  for (let a = 0; a < R; a++) {
    near.push([]);
    for (let b = 0; b < R; b++) if (a === b || far(a, b) < 18) near[a].push(b);
  }
  const left = new Set(Array.from({ length: R }, (_, i) => i));
  const groups: number[][] = [];
  while (left.size) {
    let best = -1, bestN = -1;
    left.forEach((a) => {
      const n = near[a].filter((b) => left.has(b)).length;
      if (n > bestN) {
        best = a;
        bestN = n;
      }
    });
    const g = near[best].filter((b) => left.has(b));
    g.forEach((b) => left.delete(b));
    groups.push(g.sort((x, y) => x - y));
  }
  return groups.sort((a, b) => b.length - a.length || a[0] - b[0]);
}


// ---- Preview: the real layer and caption graphics, scaled down, with a stand-in where the video goes ----
// Pictures are data URLs in the template; the preview shows them through blob URLs.
function useBlobUrls(urls: string[]): string[] {
  const key = urls.join("|").length + ":" + urls.map((u) => u.slice(-40)).join("|");
  const [out, setOut] = React.useState<string[]>(urls.map(() => ""));
  React.useEffect(() => {
    const made: string[] = [];
    const next = urls.map((u) => {
      const m = String(u || "").match(/^data:([^;,]+);base64,(.*)$/);
      if (!m) return u || "";
      try {
        const bin = atob(m[2]);
        const bytes = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
        const b = URL.createObjectURL(new Blob([bytes], { type: m[1] }));
        made.push(b);
        return b;
      } catch (e) {
        return "";
      }
    });
    setOut(next);
    return () => made.forEach((b) => URL.revokeObjectURL(b));
  }, [key]);
  return out;
}

function LayerPreview({ t, S, maxWidth = 240, still }: any) {
  const ref = React.useRef<HTMLDivElement>(null);
  const w = useWidth(ref, 180);
  const L = t.layout;
  const W = L.width || 1080;
  const H = L.height || 1920;
  const scale = w / W;
  const pics = L.images || [];
  const urls = useBlobUrls([L.background?.image || "", ...pics.map((p: any) => p.image || "")]);
  const shown = {
    ...t,
    layout: { ...L, background: { ...L.background, image: L.background?.mode === "image" ? urls[0] : "" }, images: pics.map((p: any, i: number) => ({ ...p, image: urls[i + 1] })) },
  };
  const V = L.video;
  return (
    <div ref={ref} style={{ width: "100%", maxWidth, margin: "0 auto" }}>
      <div style={{ position: "relative", width: w, height: Math.round(H * scale), overflow: "hidden", borderRadius: 6, border: "1px solid var(--panel-border)" }}>
        <div style={{ position: "absolute", left: 0, top: 0, width: W, height: H, transform: `scale(${scale})`, transformOrigin: "0 0", background: "#000" }}>
          {still ? (
            <img src={still} style={{ position: "absolute", left: V.x, top: V.y, width: V.w, height: V.h, objectFit: V.fit === "contain" ? "contain" : "cover" }} />
          ) : (
            <div
              style={{
                position: "absolute", left: V.x, top: V.y, width: V.w, height: V.h,
                background: "repeating-linear-gradient(135deg,#3A3A3A 0 48px,#474747 48px 96px)",
                display: "flex", alignItems: "center", justifyContent: "center", color: "#BDBDBD", fontSize: 80, fontWeight: 700, letterSpacing: 6,
              }}
            >
              {S.videoArea}
            </div>
          )}
          <PreviewLayers data={frameParams(shown, S.sampleH1, S.sampleH2)} />
          {t.captions.on ? <PreviewCaption data={{ ...captionParams(t), text: S.sampleCaption }} /> : null}
        </div>
      </div>
    </div>
  );
}

const SHAPES: any = { "9:16": [1080, 1920], "4:5": [1080, 1350], "1:1": [1080, 1080], "16:9": [1920, 1080] };
function shapeOf(L: any): string {
  return Object.keys(SHAPES).find((k) => SHAPES[k][0] === L.width && SHAPES[k][1] === L.height) || "9:16";
}
// A new canvas shape keeps every layer in the same relative place.
function reshape(t: any, shape: string) {
  const [W, H] = SHAPES[shape];
  const L = t.layout;
  const sx = W / (L.width || 1080);
  const sy = H / (L.height || 1920);
  const box = (b: any) => ({ ...b, x: Math.round(b.x * sx), y: Math.round(b.y * sy), w: Math.round(b.w * sx), h: Math.round(b.h * sy) });
  return {
    ...t,
    layout: { ...L, width: W, height: H, video: box(L.video), texts: (L.texts || []).map(box), images: (L.images || []).map(box) },
    captions: { ...t.captions, y: Math.round(t.captions.y * sy) },
  };
}

function newText(n: number, W: number) {
  return {
    id: "t" + Date.now().toString(36) + n, role: "static", text: "", x: 40, y: 120 + n * 140, w: W - 80, h: 120, align: "center", font: "",
    size: 72, weight: 800, color: "#FFFFFF", lineHeight: 1.18, tracking: -1, italic: false, shadow: false,
    stroke: { on: false, color: "#000000", width: 8 }, box: { on: false, color: "#000000", padX: 22, padY: 6, radius: 0, gap: 10 },
  };
}

// ---- Template editor ----
function TemplateEditor({ ui, S, lang, templates, store, onChanged, onAnalyze, state }: any) {
  const { selId, setSelId, edit: saved, setEdit: setSaved, baseKey, setBaseKey, sub, setSub } = state;
  const current = templates.find((t: any) => t.id === selId) || templates[0];
  const [msg, setMsg] = React.useState<any>(null);
  const [armed, setArmed] = React.useState(false);
  const [saving, setSaving] = React.useState(false);
  const currentKey = React.useMemo(() => JSON.stringify(current ?? null), [current]);
  React.useEffect(() => {
    if (current && (!saved || saved.id !== current.id || baseKey !== currentKey)) {
      setSaved(clone(current));
      setBaseKey(currentKey);
    }
    setArmed(false);
  }, [selId, currentKey]);
  if (!current) return null;
  const fresh = !saved || saved.id !== current.id || baseKey !== currentKey;
  const edit = fresh ? JSON.parse(currentKey) : saved;
  const setEdit = (f: any) => setSaved((e: any) => (typeof f === "function" ? f(fresh || !e ? JSON.parse(currentKey) : e) : f));
  const dirty = JSON.stringify(edit) !== currentKey;
  const get = (path: string) => path.split(".").reduce((o: any, k) => (o == null ? o : o[k]), edit);
  const set = (path: string, value: any) => {
    setMsg(null);
    setEdit((e: any) => {
      const n = clone(e);
      const ks = path.split(".");
      let o = n;
      for (let i = 0; i < ks.length - 1; i++) o = o[ks[i]];
      o[ks[ks.length - 1]] = value;
      return n;
    });
  };
  const L = edit.layout;
  const W = L.width || 1080;
  const H = L.height || 1920;
  const num = (path: string, label: string, min: number, max: number, step = 1, unit?: string) => (
    <ui.NumberField label={label} value={Number(get(path))} min={min} max={max} step={step} unit={unit} onChange={(x: number) => set(path, Math.max(min, Math.min(max, step < 1 ? x : Math.round(x))))} disabled={saving} />
  );
  const txt = (path: string, label: string, multiline = true) => <ui.TextField label={label} value={String(get(path) ?? "")} onChange={(x: string) => set(path, x)} multiline={multiline} disabled={saving} />;
  const col = (path: string, label: string) => <ui.ColorField label={label} value={String(get(path) || "#FFFFFF")} onChange={(v: string) => set(path, v)} />;
  const tog = (path: string, label: string) => <ui.Toggle label={label} value={!!get(path)} onChange={(v: boolean) => set(path, v)} disabled={saving} />;
  const seg = (path: string, label: string, options: any[]) => <ui.Segmented label={label} value={String(get(path))} onChange={(v: string) => set(path, v)} options={options} disabled={saving} />;
  const box = (base: string) => (
    <ui.Grid minItemWidth={110}>
      {num(base + ".x", S.left, -W, W, 1, "px")}
      {num(base + ".y", S.top, -H, H, 1, "px")}
      {num(base + ".w", S.width, 10, W * 2, 1, "px")}
      {num(base + ".h", S.height, 10, H * 2, 1, "px")}
    </ui.Grid>
  );
  const weights = [300, 400, 500, 600, 700, 800, 900].map((w) => ({ value: String(w), label: String(w) }));
  const clean = (t: any) => {
    const { builtIn, modified, ...rest } = t;
    return rest;
  };

  async function save() {
    setSaving(true);
    try {
      await store.put("templates", edit.id, clean(edit));
      await onChanged();
      setMsg({ tone: "success", text: S.savedOk });
    } catch (e: any) {
      setMsg({ tone: "error", text: String(e?.message || e) });
    } finally {
      setSaving(false);
    }
  }
  async function duplicate() {
    const id = "t" + Date.now().toString(36);
    setSaving(true);
    try {
      await store.put("templates", id, { ...clean(clone(edit)), id, baseId: undefined, name: S.copyName(nameOf(edit, lang)) });
      await onChanged();
      setSelId(id);
    } catch (e: any) {
      setMsg({ tone: "error", text: String(e?.message || e) });
    } finally {
      setSaving(false);
    }
  }
  async function reset() {
    setSaving(true);
    try {
      await store.del("templates", current.id);
      await onChanged();
    } finally {
      setSaving(false);
    }
  }
  async function remove() {
    if (!armed) return setArmed(true);
    setSaving(true);
    try {
      if (current.builtIn) await store.put("templates", current.id, { id: current.id, deleted: true });
      else await store.del("templates", current.id);
      const left = await onChanged();
      setSelId((left || templates).find((x: any) => x.id !== current.id)?.id || "");
    } finally {
      setSaving(false);
      setArmed(false);
    }
  }
  async function pick(path: string, kind: "background" | "picture", f: any, after?: (info: any) => void) {
    if (!f?.path || !store.fs) return;
    try {
      const r = await fileToDataUrl(store.fs, f.path, kind, W, H);
      set(path, r.url);
      if (after) after(r);
    } catch (e) {
      setMsg({ tone: "error", text: S.imageFailed });
    }
  }

  const preview = (
    <ui.Section title={S.preview}>
      <LayerPreview t={edit} S={S} still={edit.source?.still || ""} />
    </ui.Section>
  );

  const layout = (
    <ui.Stack gap={16}>
      {preview}
      <ui.Section title={S.canvas}>
        <ui.Segmented label={S.shape} value={shapeOf(L)} onChange={(v: string) => setEdit((e: any) => reshape(e, v))} options={Object.keys(SHAPES).map((k) => ({ value: k, label: k }))} disabled={saving} />
      </ui.Section>
      <ui.Section title={S.background}>
        {seg("layout.background.mode", S.background, [
          { value: "color", label: S.bgColor },
          { value: "image", label: S.bgImage },
          { value: "none", label: S.bgNone },
        ])}
        {L.background.mode !== "none" && col("layout.background.color", S.color)}
        {L.background.mode === "image" && (
          <ui.Stack gap={8}>
            <ui.FileDrop accept={["image"]} value={L.background.imageName ? { path: "", name: L.background.imageName } : null} onChange={(f: any) => pick("layout.background.image", "background", f, () => set("layout.background.imageName", f?.name || ""))} disabled={saving} />
            {num("layout.background.dim", S.dim, 0, 90, 1, "%")}
          </ui.Stack>
        )}
      </ui.Section>
      <ui.Section title={S.videoBox}>
        {box("layout.video")}
        {seg("layout.video.fit", S.fit, [
          { value: "cover", label: S.fitCover },
          { value: "contain", label: S.fitContain },
        ])}
        {L.video.fit !== "contain" && num("layout.video.zoom", S.zoom, 1, 4, 0.05, "×")}
        {num("layout.video.focusX", S.focusX, 0, 1, 0.01)}
        {num("layout.video.focusY", S.focusY, 0, 1, 0.01)}
        {tog("layout.video.border.on", S.border)}
        {L.video.border?.on && (
          <ui.Stack gap={8}>
            {col("layout.video.border.color", S.color)}
            {num("layout.video.border.width", S.borderWidth, 1, 60, 1, "px")}
          </ui.Stack>
        )}
      </ui.Section>
    </ui.Stack>
  );

  const texts = (
    <ui.Stack gap={16}>
      {preview}
      {(L.texts || []).map((t: any, i: number) => {
        const b = `layout.texts.${i}`;
        return (
          <ui.Section key={t.id || i} title={S.textLayer(i + 1)}>
            <ui.Select
              label={S.role}
              value={t.role}
              onChange={(v: string) => set(b + ".role", v)}
              options={[
                { value: "headline1", label: S.roleH1 },
                { value: "headline2", label: S.roleH2 },
                { value: "static", label: S.roleStatic },
              ]}
              disabled={saving}
            />
            {t.role === "static" && txt(b + ".text", S.fixedText)}
            {box(b)}
            {seg(b + ".align", S.align, [
              { value: "left", label: S.alignLeft },
              { value: "center", label: S.alignCenter },
              { value: "right", label: S.alignRight },
            ])}
            {num(b + ".size", S.size, 12, 240, 1, "px")}
            <ui.Select label={S.weight} value={String(t.weight)} onChange={(v: string) => set(b + ".weight", Number(v))} options={weights} disabled={saving} />
            {col(b + ".color", S.color)}
            <ui.FontField label={S.font} value={t.font || ""} onChange={(v: string) => set(b + ".font", v)} />
            {tog(b + ".italic", S.italic)}
            {tog(b + ".shadow", S.shadow)}
            {tog(b + ".stroke.on", S.outline)}
            {t.stroke?.on && (
              <ui.Stack gap={8}>
                {col(b + ".stroke.color", S.outlineColor)}
                {num(b + ".stroke.width", S.outlineWidth, 1, 40, 1, "px")}
              </ui.Stack>
            )}
            {tog(b + ".box.on", S.textBox)}
            {t.box?.on && col(b + ".box.color", S.boxColor)}
            <ui.Actions>
              <ui.Button variant="ghost" onClick={() => setEdit((e: any) => ({ ...e, layout: { ...e.layout, texts: e.layout.texts.filter((_: any, k: number) => k !== i) } }))} disabled={saving}>
                {S.remove}
              </ui.Button>
            </ui.Actions>
          </ui.Section>
        );
      })}
      <ui.Actions>
        <ui.Button variant="secondary" onClick={() => setEdit((e: any) => ({ ...e, layout: { ...e.layout, texts: [...(e.layout.texts || []), newText((e.layout.texts || []).length, W)] } }))} disabled={saving}>
          {S.addText}
        </ui.Button>
      </ui.Actions>
    </ui.Stack>
  );

  const pictures = (
    <ui.Stack gap={16}>
      {preview}
      <small>{S.pictureHint}</small>
      {(L.images || []).map((p: any, i: number) => {
        const b = `layout.images.${i}`;
        return (
          <ui.Section key={p.id || i} title={S.pictureLayer(i + 1)}>
            <ui.FileDrop accept={["image"]} value={p.name ? { path: "", name: p.name } : null} onChange={(f: any) => pick(b + ".image", "picture", f, () => set(b + ".name", f?.name || ""))} disabled={saving} />
            {box(b)}
            <ui.Actions>
              <ui.Button variant="ghost" onClick={() => setEdit((e: any) => ({ ...e, layout: { ...e.layout, images: e.layout.images.filter((_: any, k: number) => k !== i) } }))} disabled={saving}>
                {S.remove}
              </ui.Button>
            </ui.Actions>
          </ui.Section>
        );
      })}
      <ui.Section title={S.addPicture}>
        <ui.FileDrop
          accept={["image"]}
          value={null}
          onChange={async (f: any) => {
            if (!f?.path || !store.fs) return;
            try {
              const r = await fileToDataUrl(store.fs, f.path, "picture", W, H);
              const w = Math.min(Math.round(W * 0.4), r.w);
              const h = Math.round((w * r.h) / Math.max(1, r.w));
              setEdit((e: any) => ({ ...e, layout: { ...e.layout, images: [...(e.layout.images || []), { id: "p" + Date.now().toString(36), role: "picture", x: Math.round((W - w) / 2), y: H - h - 120, w, h, image: r.url, name: f.name || "" }] } }));
            } catch (e) {
              setMsg({ tone: "error", text: S.imageFailed });
            }
          }}
          disabled={saving}
        />
      </ui.Section>
    </ui.Stack>
  );

  const captions = (
    <ui.Stack gap={16}>
      {preview}
      <ui.Section title={S.captionsOn}>
        {tog("captions.on", S.captionsOn)}
        {edit.captions.on && (
          <ui.Stack gap={8}>
            {seg("captions.style", S.captionStyle, [
              { value: "box", label: S.capBox },
              { value: "outline", label: S.capOutline },
              { value: "shadow", label: S.capShadow },
              { value: "plain", label: S.capPlain },
            ])}
            {num("captions.y", S.captionLine, 0, H, 1, "px")}
            {num("captions.fontSize", S.size, 20, 160, 1, "px")}
            <ui.Select label={S.weight} value={String(edit.captions.fontWeight)} onChange={(v: string) => set("captions.fontWeight", Number(v))} options={weights} disabled={saving} />
            {col("captions.color", S.color)}
            {edit.captions.style === "box" && col("captions.boxColor", S.boxColor)}
            <ui.FontField label={S.font} value={edit.captions.font || ""} onChange={(v: string) => set("captions.font", v)} />
            {num("captions.lineMax", S.lineMax, 6, 40, 1)}
          </ui.Stack>
        )}
      </ui.Section>
      <ui.Section title={S.editing}>
        {tog("editing.removeFillers", S.removeFillers)}
        {tog("editing.removeSilences", S.removeSilences)}
      </ui.Section>
    </ui.Stack>
  );

  const ai = (
    <ui.Stack gap={16}>
      <small>{S.promptHint}</small>
      <ui.Section title={S.subAI}>
        {txt("prompt.role", S.pRole)}
        {txt("prompt.format", S.pFormat)}
        {txt("prompt.good", S.pGood)}
        {txt("prompt.bad", S.pBad)}
        {txt("prompt.lengthGuide", S.pLength, false)}
        {txt("prompt.countGuide", S.pCount)}
        {txt("prompt.rules", S.pRules)}
        {txt("prompt.headline", S.pHeadline)}
      </ui.Section>
    </ui.Stack>
  );

  const refs = edit.source?.references || [];
  const note = current.builtIn ? S.builtInNote : refs.length ? S.learnedFrom(refs.length, edit.source?.channel || "") : S.customNote;
  return (
    <ui.Stack gap={16}>
      <ui.Section title={S.template}>
        <ui.Select label={S.template} value={current.id} onChange={(v: string) => setSelId(v)} options={templates.map((x: any) => ({ value: x.id, label: nameOf(x, lang) }))} disabled={dirty || saving} />
        <small>
          {descOf(edit, lang)}
          {descOf(edit, lang) ? " · " : ""}
          {note}
        </small>
        <ui.TextField label={S.tplName} value={nameOf(edit, lang)} onChange={(v: string) => set("name", v)} disabled={saving} />
        <ui.Row gap={8}>
          <ui.Button variant="secondary" onClick={onAnalyze} disabled={dirty || saving}>
            {S.newFromRefs}
          </ui.Button>
          <ui.Button variant="secondary" onClick={duplicate} disabled={dirty || saving}>
            {S.duplicate}
          </ui.Button>
          {current.builtIn && current.modified && (
            <ui.Button variant="ghost" onClick={reset} disabled={dirty || saving}>
              {S.reset}
            </ui.Button>
          )}
          <ui.Button variant="danger" onClick={remove} disabled={dirty || saving || templates.length <= 1}>
            {armed ? S.delConfirm : S.del}
          </ui.Button>
        </ui.Row>
      </ui.Section>
      <ui.Tabs
        value={sub}
        onChange={setSub}
        tabs={[
          { value: "layout", label: S.subLayout, content: layout },
          { value: "text", label: S.subText, content: texts },
          { value: "pictures", label: S.subPictures, content: pictures },
          { value: "captions", label: S.subCaptions, content: captions },
          { value: "ai", label: S.subAI, content: ai },
        ]}
      />
      {dirty && <ui.Message>{S.unsaved}</ui.Message>}
      {msg && <ui.Message tone={msg.tone}>{msg.text}</ui.Message>}
      <ui.Actions>
        <ui.Button variant="ghost" onClick={() => setEdit(clone(current))} disabled={!dirty || saving}>
          {S.discard}
        </ui.Button>
        <ui.Button variant="primary" busy={saving} onClick={save} disabled={!dirty}>
          {S.save}
        </ui.Button>
      </ui.Actions>
    </ui.Stack>
  );
}


function Panel(props: any) {
  return <ProjectPanel key={String(props.context.projectId)} {...props} />;
}
function ProjectPanel({ sdk, context, ui }: any) {
  hostUseSdk(sdk);
  const lang = langOf(context);
  const S = STRINGS[lang] ?? STRINGS.en;
  const projectId: string | null = context?.projectId ?? null;
  const store = React.useMemo(() => makeStore(), []);
  const [tab, setTab] = React.useState<string>("make");
  const [templates, setTemplates] = React.useState<any[]>(BUILTIN_TEMPLATES.map((t: any) => ({ ...t, builtIn: true })));
  const [mode, setMode] = React.useState<string>("link");
  const [url, setUrl] = React.useState<string>("");
  const [resources, setResources] = React.useState<any[]>([]);
  const [pick, setPick] = React.useState<string | null>(null);
  const [tplId, setTplId] = React.useState<string>(BUILTIN_TEMPLATES[0].id);
  const [countMode, setCountMode] = React.useState<string>("auto");
  const [count, setCount] = React.useState<number>(3);
  const [note, setNote] = React.useState<string>("");
  const [busy, setBusy] = React.useState<boolean>(false);
  const [step, setStep] = React.useState<number>(-1);
  const [status, setStatus] = React.useState<string>("");
  const [error, setError] = React.useState<string>("");
  const [info, setInfo] = React.useState<any>(null);
  const [drafts, setDrafts] = React.useState<any[]>([]);
  const [jobs, setJobs] = React.useState<any[]>([]);
  // Templates tab
  const [tplSel, setTplSel] = React.useState<string>(BUILTIN_TEMPLATES[0].id);
  const [tplEdit, setTplEdit] = React.useState<any>(null);
  const [tplBase, setTplBase] = React.useState<string>("");
  const [tplSub, setTplSub] = React.useState<string>("layout");
  const [refsView, setRefsView] = React.useState<boolean>(false);
  const [refsText, setRefsText] = React.useState<string>("");
  const [refsName, setRefsName] = React.useState<string>("");
  const [aStep, setAStep] = React.useState<number>(-1);
  const [aStatus, setAStatus] = React.useState<string>("");
  const [aError, setAError] = React.useState<string>("");
  const [aBusy, setABusy] = React.useState<boolean>(false);

  const resolver = (resourceId: string, resourceName: string) =>
    `const project = selects.project(${JSON.stringify(projectId)}); const rows = await project.resources(); ` +
    `const res = rows.find((r: any) => r.resourceId === ${JSON.stringify(resourceId)} && (${JSON.stringify(!resourceName)} || r.name === ${JSON.stringify(resourceName)})) || rows.find((r: any) => r.name === ${JSON.stringify(resourceName)}) || rows.find((r: any) => r.resourceId === ${JSON.stringify(resourceId)}) || null; `;
  const script = async (code: string, summary: string, allowCommit = false) => {
    if (activeProject.current !== projectId) throw new Error("The project changed. Reopen the saved job in its original project.");
    const r: any = await sdk.runScript({ script: code, summary, allowCommit });
    if (r.isError) throw new Error(scriptError(r.output));
    return r.result;
  };
  // Selects caps a shell call at 48 KB of output and five minutes; every call goes through here, so no
  // call can ask for more. Anything that may print more is written to a file and read back instead.
  const shell = async (command: string, summary: string, timeoutMs = 120000) => {
    const cmd = IS_WIN ? "@echo off\r\n" + command.replace(/\r?\n/g, "\r\n") : command;
    const r: any = await sdk.runShell({ summary, command: cmd, timeoutMs: Math.min(timeoutMs, SHELL_MAX_MS), maxOutputBytes: SHELL_MAX_OUTPUT });
    return { ...r, stdout: String(r.stdout || ""), stderr: String(r.stderr || ""), output: String(r.output || "") };
  };

  // ---- Templates: built-ins, changed or extended by files saved on this computer ----
  const loadTemplates = React.useCallback(async () => {
    try {
      const saved: any[] = (await store.list("templates")).filter((t: any) => t && t.id && t.version === 2 || (t && t.deleted));
      const byId = new Map(saved.map((t) => [t.id, t]));
      const list: any[] = BUILTIN_TEMPLATES.filter((b: any) => !byId.get(b.id)?.deleted).map((b: any) =>
        byId.has(b.id) ? { ...merge(b, byId.get(b.id)), builtIn: true, modified: true } : { ...b, builtIn: true }
      );
      for (const t of saved) {
        if (t.deleted || BUILTIN_TEMPLATES.some((b: any) => b.id === t.id)) continue;
        list.push({ ...t, builtIn: false });
      }
      list.sort((a, b) => (a.builtIn === b.builtIn ? String(b.created || "").localeCompare(String(a.created || "")) : a.builtIn ? 1 : -1));
      setTemplates(list);
      return list;
    } catch (e: any) {
      setError(String(e?.message || e));
      return null;
    }
  }, [store]);
  React.useEffect(() => {
    loadTemplates();
  }, [loadTemplates]);
  React.useEffect(() => {
    if (templates.length && !templates.some((t) => t.id === tplId)) setTplId(templates[0].id);
    if (templates.length && !templates.some((t) => t.id === tplSel)) setTplSel(templates[0].id);
  }, [templates]);

  // ---- Saved progress ----
  const saveJob = async (job: any) => store.put("jobs", job.id, job);
  const activeProject = React.useRef(projectId);
  activeProject.current = projectId;
  React.useEffect(() => { activeProject.current = projectId; return () => { activeProject.current = null; }; }, []);
  const loadJobs = React.useCallback(async () => {
    if (!projectId) return;
    try {
      const since = Date.now() - 14 * 24 * 3600 * 1000;
      const list = (await store.list("jobs"))
        .filter((j: any) => j && j.version === 3 && j.projectId === projectId && !j.done && !j.dismissed && Date.parse(j.updated || j.created || "") > since)
        .sort((a: any, b: any) => String(b.updated).localeCompare(String(a.updated)));
      if (activeProject.current === projectId) setJobs(list);
    } catch (e: any) { if (activeProject.current === projectId) setError(String(e?.message || e)); }
  }, [projectId, store]);
  React.useEffect(() => {
    loadJobs();
  }, [loadJobs]);

  const loadResources = React.useCallback(async () => {
    if (!projectId) return;
    try {
      const rows = (await readMediaPages(sdk, {script: `return (await selects.project(${JSON.stringify(projectId)}).resources()).filter((r: any) => r.type === "Video").map((r: any) => ({ id: r.resourceId, name: r.name, analyzed: r.hasAnalysis, sec: Math.round(r.durationSeconds ?? 0) }));`, summary: "List project videos"})).result;
      if (activeProject.current === projectId) setResources(rows || []);
    } catch (e: any) {
      setError(String(e?.message || e));
    }
  }, [projectId]);
  React.useEffect(() => {
    loadResources();
  }, [loadResources]);

  // ---- Programs: yt-dlp is fetched into the app's folder when missing; ffmpeg comes with Selects ----
  async function dataPaths() {
    if (!store.root) throw new Error(S.noFileAccess);
    return store;
  }
  async function findTools(): Promise<{ ytdlp: string | null; ffmpeg: string | null }> {
    const P = await dataPaths();
    const own = P.join(P.bin, IS_WIN ? "yt-dlp.exe" : "yt-dlp");
    let cmd: string;
    if (IS_WIN) {
      // Check the known install locations through the host FileSystem first: no console code page for a
      // Korean profile path, and no reliance on %ProgramFiles% in the shell's environment.
      const apps = ["Selects", "Selects Staging", "Selects Delta"];
      const roots = [store.join(store.fs.homedir(), "AppData", "Local", "Programs"), "C:\\Program Files", "C:\\Program Files (x86)"];
      const known = roots.flatMap((r) => apps.map((a) => store.join(r, a, "resources", "app.asar.unpacked", "dist", "bin", "ffmpeg.exe")));
      let ffmpeg: string | null = null;
      for (const file of known) { if (await store.exists(file)) { ffmpeg = file; break; } }
      if (ffmpeg && await store.exists(own)) return { ytdlp: own, ffmpeg };
      if (ffmpeg) {
        const r = await shell(`for /f "delims=" %%i in ('where yt-dlp.exe 2^>nul') do echo Y=%%i\nexit /b 0`, "Find the video tools", 60000);
        const y = r.stdout.split(/\r?\n/).map((l: string) => l.trim()).find((l: string) => l.startsWith("Y="));
        return { ytdlp: y ? y.slice(2).trim() : null, ffmpeg };
      }
      const local = store.join(store.fs.homedir(), "AppData", "Local", "Programs");
      const bundled = ["Selects", "Selects Staging"].map((a) => store.join(local, a, "resources", "app.asar.unpacked", "dist", "bin", "ffmpeg.exe"));
      cmd = [
        `if exist ${wq(own)} echo Y=OWN`,
        ...bundled.map((f, i) => `if exist ${wq(f)} echo F=BUNDLED${i}`),
        // A per-machine install (ASCII path, so it reads back through the console unchanged).
        `for %%a in ("Selects" "Selects Staging") do if exist "%ProgramFiles%\\%%~a\\resources\\app.asar.unpacked\\dist\\bin\\ffmpeg.exe" echo F=%ProgramFiles%\\%%~a\\resources\\app.asar.unpacked\\dist\\bin\\ffmpeg.exe`,
        `for /f "delims=" %%i in ('where yt-dlp.exe 2^>nul') do echo Y=%%i`,
        `for /f "delims=" %%i in ('where ffmpeg.exe 2^>nul') do echo F=%%i`,
        `exit /b 0`,
      ].join("\n");
    } else {
      const apps = ["Selects", "Selects Staging", "Selects Delta"].map((a) => pq(`/Applications/${a}.app/Contents/Resources/app.asar.unpacked/dist/bin/ffmpeg`)).join(" ");
      cmd =
        `for p in ${pq(own)} "$(command -v yt-dlp 2>/dev/null)" "$HOME/.local/bin/yt-dlp" /opt/homebrew/bin/yt-dlp /usr/local/bin/yt-dlp; do [ -n "$p" ] && [ -x "$p" ] && echo "Y=$p"; done; ` +
        `for p in ${apps} "$(command -v ffmpeg 2>/dev/null)" /opt/homebrew/bin/ffmpeg /usr/local/bin/ffmpeg; do [ -n "$p" ] && [ -x "$p" ] && echo "F=$p"; done; true`;
    }
    const r = await shell(cmd, "Find the video tools", 60000);
    const lines = r.stdout.split(/\r?\n/).map((l: string) => l.trim());
    const first = (p: string) => {
      const l = lines.find((x: string) => x.startsWith(p + "="));
      return l ? l.slice(p.length + 1).trim() : null;
    };
    const y = first("Y");
    const f = first("F");
    const bundledPath = (i: number) => store.join(store.fs.homedir(), "AppData", "Local", "Programs", ["Selects", "Selects Staging"][i], "resources", "app.asar.unpacked", "dist", "bin", "ffmpeg.exe");
    return { ytdlp: y === "OWN" ? own : y, ffmpeg: f && /^BUNDLED\d$/.test(f) ? bundledPath(Number(f.slice(7))) : f };
  }
  async function installYtdlp(): Promise<string> {
    const P = await dataPaths();
    await store.ensure(P.bin);
    const target = P.join(P.bin, IS_WIN ? "yt-dlp.exe" : "yt-dlp");
    const part = target + ".part";
    const cmd = IS_WIN
      ? [`curl.exe -fsSL --retry 3 -o ${wq(part)} ${wq(YTDLP_URL)} || exit /b 1`, `move /y ${wq(part)} ${wq(target)} >nul || exit /b 1`, `${wq(target)} --version`].join("\n")
      : `curl -fsSL --retry 3 -o ${pq(part)} ${pq(YTDLP_URL)} && mv -f ${pq(part)} ${pq(target)} && chmod +x ${pq(target)} && ${pq(target)} --version`;
    const r = await shell(cmd, "Get the downloader", 290000);
    if (r.exitCode === 0 && /\d{4}\.\d{2}\.\d{2}/.test(r.stdout)) return target;
    if (typeof store.fs.downloadFile === "function") {
      await store.fs.downloadFile(YTDLP_URL, target);
      const v = await shell(IS_WIN ? `${wq(target)} --version` : `chmod +x ${pq(target)} && ${pq(target)} --version`, "Check the downloader", 120000);
      if (v.exitCode === 0) return target;
    }
    throw new Error(S.downloadFailed + (r.stderr || r.output || "").slice(-300));
  }
  // Called before every download; nothing about it is shown unless it fails.
  async function tools() {
    let t = await findTools();
    if (!t.ytdlp) t = { ...t, ytdlp: await installYtdlp() };
    return t as { ytdlp: string; ffmpeg: string | null };
  }

  // One download with retries. Some sites refuse anonymous downloads; then the browsers' own sign-in is
  // tried, one browser at a time (the values stay on this computer).
  const BROWSERS = IS_WIN ? ["firefox", "edge", "chrome", "brave"] : ["chrome", "safari", "firefox", "edge", "brave"];
  async function download(link: string, dir: string, format: string, onTry: (n: number) => void) {
    const T = await tools();
    await store.ensure(dir);
    const Y = qa(T.ytdlp);
    const fmt = T.ffmpeg ? format : "b[ext=mp4]/b";
    const base =
      `${Y} --no-warnings --no-progress --encoding utf-8 --no-playlist -N 4 -f ${qa(fmt)} --merge-output-format mp4 ` +
      (T.ffmpeg ? `--ffmpeg-location ${qa(T.ffmpeg)} ` : "") +
      `-o ${qa(store.join(dir, "%(id)s.%(ext)s"))} --print ${qa("after_move:INFO\t%(id)s\t%(duration)s\t%(view_count)s\t%(width)s\t%(height)s\t%(filepath)s\t%(title)s")} --no-simulate ${qa(link)}`;
    let last = "";
    const tries = [null, null, ...BROWSERS];
    for (let i = 0; i < tries.length; i++) {
      onTry(i + 1);
      const r = await shell(base + (tries[i] ? ` --cookies-from-browser ${tries[i]}` : ""), "Download a video", 290000);
      const line = r.stdout.split(/\r?\n/).find((l: string) => l.startsWith("INFO\t"));
      if (line) {
        const [, id, dur, views, w, h, file, ...title] = line.split("\t");
        if (file && await store.exists(file.trim())) return { id, duration: Number(dur) || 0, views: Number(views) || null, w: Number(w) || 0, h: Number(h) || 0, file: file.trim(), title: title.join("\t").trim() };
      }
      last = (r.stderr || r.output || "").slice(-400);
    }
    throw new Error(S.downloadFailed + last);
  }

  // ---- Make shorts: source → transcript → moments → Drafts ----
  async function prepareFromLink(link: string) {
    setStatus(S.preparing);
    const P = await dataPaths();
    const got = await download(link, P.media, "bv*[height<=1080][vcodec^=avc1]+ba[ext=m4a]/b[height<=1080][ext=mp4]/bv*[height<=1080]+ba/b", (n) => setStatus(S.downloading("", n)));
    const existing = await script(
      `const r = (await selects.project(${JSON.stringify(projectId)}).resources()).find((r: any) => String(r.name).includes(${JSON.stringify(got.id)})); return r ? { id: r.resourceId, name: r.name } : null;`,
      "Look for an earlier import"
    );
    if (existing?.id) return { resourceId: existing.id, resourceName: existing.name, title: got.title };
    const imp = await script(
      `const p = selects.project(${JSON.stringify(projectId)}); const imp = await p.importFiles({ paths: [${JSON.stringify(got.file)}] }); const id = imp?.addedResourceIds?.[0]; const r = id ? (await p.resources()).find((x: any) => x.resourceId === id) : null; return r ? { id, name: r.name } : null;`,
      "Import the video",
      true
    );
    if (!imp?.id) throw new Error(S.importFailed);
    return { resourceId: imp.id, resourceName: imp.name, title: got.title };
  }

  async function ensureAnalyzed(resourceId: string, resourceName: string) {
    const st = async () => script(resolver(resourceId, resourceName) + `return res ? { status: res.status, has: res.hasAnalysis } : null;`, "Check analysis status");
    let s = await st();
    if (s?.has) return;
    if (s && ["pending", "samplingFailed", "analyzingFailed"].includes(s.status)) {
      // Selects asks the user to approve the credits in its own window and closes that request when this
      // script's 30 seconds run out. An unanswered or declined request comes back as a failed script.
      setStatus(S.confirmCredits);
      let begun: any = null;
      try {
        begun = await script(
          resolver(resourceId, resourceName) + `if (!res) throw new Error("The source video is no longer in this project."); return await project.startAnalysis({ resourceIds: [res.resourceId] });`,
          "Transcribe the source video",
          true
        );
      } catch (e: any) {
        if (/Analysis canceled by user|confirmation deadline/i.test(String(e?.message || e))) throw new Error(S.confirmMissed);
        throw e;
      }
      if (begun?.cancelled) throw new Error(S.confirmMissed);
      const refused = (begun?.skipped || []).find((x: any) => !["analysis_in_progress", "already_analyzed"].includes(x?.reason));
      if (!begun?.started?.length && refused) throw new Error(S.analysisFailed(String(refused.message || refused.reason)));
    }
    setStatus(S.waitingAnalysis);
    const t0 = Date.now();
    while (Date.now() - t0 < 45 * 60 * 1000) {
      await sleep(10000);
      s = await st();
      if (s?.has) return;
      if (s && /Failed$/.test(s.status)) throw new Error(S.analysisFailed(s.status));
    }
    throw new Error(S.analysisSlow);
  }

  async function readTranscript(resourceId: string, resourceName: string) {
    const lines: any[] = [];
    let duration = 0;
    for (let off = 0; off < 5000; off += 250) {
      const r = await script(SCRIPT_TRANSCRIPT.replace("const P: any = __P__;", "const P: any = " + JSON.stringify({ projectId, resourceId, resourceName, offset: off, limit: 250 }) + ";"), "Read the transcript");
      duration = r.duration;
      lines.push(...r.lines);
      if (off + 250 >= r.total) break;
    }
    return { lines, duration };
  }

  async function choose(tpl: any, title: string, lines: any[], duration: number, cMode: string, cNum: number, cNote: string) {
    const p = tpl.prompt;
    let tx = lines.map((l) => `[${l[0]}-${l[1]}] ${l[2]}`).join("\n");
    let truncated = false;
    if (tx.length > 90000) {
      tx = tx.slice(0, 90000);
      truncated = true;
    }
    const want = cMode === "manual" ? `Make exactly ${cNum} shorts.` : `Recommend how many shorts to make. ${p.countGuide} Make fewer when strong moments are scarce; never fill with weak ones.`;
    const prompt = [
      `${p.role} Choose passages from the long video below (${Math.round(duration)} seconds) to cut into vertical shorts.`,
      `Title or file name: ${title}`,
      `Source format: ${p.format}`,
      `Moments that do well on this channel: ${p.good}`,
      `Moments that do poorly: ${p.bad}`,
      `Rules: ${p.rules} Length of each short in the source: ${p.lengthGuide}.`,
      `Headlines: ${p.headline}`,
      want,
      cNote ? `Extra request from the user: ${cNote}` : "",
      `Each transcript line is [start-end seconds] sentence. Start every segment exactly at a line's start and end it exactly at a line's end.` + (truncated ? " The transcript was cut short; read the rest with the project tools if you need it." : ""),
      `Also list spelling fixes for the captions: names, places or numbers the transcript got wrong, as {"from": transcript spelling, "to": correct spelling}. Do not use editing tools.`,
      `Answer with JSON only: {"recommendedCount": n, "countReason": "one or two sentences", "clips": [{"headline1": "...", "headline2": "...", "segments": [[start, end]], "why": "one sentence"}], "fixes": [{"from": "...", "to": "..."}]}`,
      `Transcript:\n${tx}`,
    ]
      .filter(Boolean)
      .join("\n\n");
    const r = await sdk.askAI({ prompt, timeoutMs: 600000 });
    const j = extractJson(r.text, S);
    let clips = (j.clips || []).filter((c: any) => Array.isArray(c.segments) && c.segments.length);
    clips = clips
      .map((c: any) => ({
        ...c,
        segments: c.segments
          .map((x: any) => [Math.max(0, Number(x[0])), Math.min(duration, Number(x[1]))])
          .filter((x: any) => x[1] - x[0] > 1)
          .sort((a: any, b: any) => a[0] - b[0]),
      }))
      .filter((c: any) => c.segments.length);
    if (cMode === "manual") clips = clips.slice(0, cNum);
    return { clips, recommendedCount: j.recommendedCount ?? clips.length, countReason: j.countReason || "", fixes: Array.isArray(j.fixes) ? j.fixes : [] };
  }

  async function run(resume?: any) {
    setError("");
    setDrafts([]);
    setInfo(null);
    if (!projectId) return setError(S.noProject);
    if (!resume && mode === "link" && !/^https?:\/\//.test(url.trim())) return setError(S.needUrl);
    if (!resume && mode === "project" && !pick) return setError(S.needPick);
    if (!resume && !templates.some((t) => t.id === tplId)) return setError(S.needTemplate);
    setBusy(true);
    let job: any = resume ?? { id: Date.now().toString(36), version: 3, projectId, created: new Date().toISOString(), mode, url: url.trim(), pick, templateId: tplId, countMode, count, note };
    const persist = async (patch: any) => {
      job = { ...job, ...patch, updated: new Date().toISOString() };
      await saveJob(job);
      if (activeProject.current !== job.projectId) throw new Error("The project changed. Reopen this job in its original project.");
    };
    try {
      const list = (await loadTemplates()) || templates;
      const tpl = list.find((t: any) => t.id === job.templateId);
      if (!tpl) throw new Error(S.templateGone);
      await persist({});
      setJobs((js) => js.filter((j) => j.id !== job.id));
      setStep(0);
      if (!job.resourceId) {
        if (job.mode === "link") {
          const r = await prepareFromLink(job.url);
          await persist({ resourceId: r.resourceId, resourceName: r.resourceName, title: r.title });
        } else {
          const nm = resources.find((r) => r.id === job.pick)?.name || "";
          await persist({ resourceId: job.pick, resourceName: nm, title: nm });
        }
      }
      setStep(1);
      if (!job.analyzed) {
        await ensureAnalyzed(job.resourceId, job.resourceName || "");
        await persist({ analyzed: true });
      }
      const { lines, duration } = await readTranscript(job.resourceId, job.resourceName || "");
      if (!lines.length) throw new Error(S.emptyTranscript);
      setStep(2);
      setStatus(S.choosing);
      if (!job.choice) {
        const picked = await choose(tpl, job.title || "", lines, duration, job.countMode, job.count, job.note);
        if (!picked.clips.length) throw new Error(S.noPassage);
        // Names are fixed here so a resumed job finds the Drafts it already made.
        picked.clips = picked.clips.map((c: any, i: number) => ({ ...c, name: `${nameOf(tpl, lang)} ${i + 1} · ${String(c.headline1).replace(/["“”]/g, "").slice(0, 28)} · ${job.id}` }));
        await persist({ choice: picked });
      }
      const picked = job.choice;
      setInfo({ recommended: picked.recommendedCount, countReason: picked.countReason });
      setStep(3);
      const made: any[] = Array.isArray(job.built) ? job.built.slice() : [];
      for (let i = 0; i < picked.clips.length; i++) {
        const c = picked.clips[i];
        if (made[i]?.draftId) continue;
        setStatus(S.building(i + 1, picked.clips.length, c.headline1));
        const found = await script(
          `const m = await selects.project(${JSON.stringify(projectId)}).meta(); for (const id of m.draftIds) { const dm = await selects.draft(id).meta(); if (dm.name === ${JSON.stringify(c.name)}) return { draftId: id, seconds: Math.round(dm.durationSeconds * 10) / 10 }; } return null;`,
          "Check for an existing Draft"
        );
        if (found?.draftId) {
          made[i] = { ...c, draftId: found.draftId, seconds: found.seconds };
        } else {
          if (job.pendingDraft === c.name) throw new Error("This Draft may already exist. Inspect the project and retry recovery; creation has not been repeated.");
          const P = {
            projectId,
            resourceId: job.resourceId,
            resourceName: job.resourceName || "",
            name: c.name,
            segments: c.segments,
            layout: { width: tpl.layout.width, height: tpl.layout.height, video: tpl.layout.video },
            frame: frameParams(tpl, c.headline1, c.headline2),
            editableFrame: editableFrame(S),
            caption: tpl.captions.on ? captionParams(tpl) : null,
            editableCaption: editableCaption(S),
            captions: !!tpl.captions.on,
            removeFillers: !!tpl.editing.removeFillers,
            removeSilences: !!tpl.editing.removeSilences,
            lineMax: tpl.captions.lineMax || 16,
            fixes: picked.fixes,
            preview: null,
          };
          try {
            const code = SCRIPT_BUILD.replace("const P: any = __P__;", "const P: any = " + JSON.stringify(P) + ";");
            if (code.length > SCRIPT_LIMIT) throw new Error(S.imagesTooLarge);
            await persist({ pendingDraft: c.name });
            const r = await script(code, `Build ${c.name}`, true);
            made[i] = { ...c, draftId: r?.draftId, seconds: r?.seconds };
          } catch (e: any) {
            throw e;
          }
        }
        setDrafts(made.filter(Boolean));
        await persist({ built: made, pendingDraft: null });
      }
      const allBuilt = made.length === picked.clips.length && made.every((m) => m && m.draftId);
      await persist({ done: allBuilt });
      setStatus(S.done(made.filter((m) => m && m.draftId).length));
      if (!allBuilt) setError(made.filter((m) => m && m.error).map((m) => m.error).join(" / ").slice(0, 600) + " " + S.resumeHint);
      setStep(4);
      loadResources();
    } catch (e: any) {
      setError(String(e?.message || e) + " " + S.resumeHint);
      loadJobs();
    } finally {
      setBusy(false);
    }
  }

  async function dismissJob(job: any) {
    await saveJob({ ...job, dismissed: true, updated: new Date().toISOString() });
    loadJobs();
  }
  async function openDraft(id: string) {
    try {
      await script(`return await selects.editor.openDraft(${JSON.stringify(id)});`, "Open the Draft");
    } catch (e: any) {
      setError(String(e?.message || e));
    }
  }

  // ---- New template from reference shorts ----
  async function frames(file: string, dir: string, duration: number, sw: number, sh: number, W: number, H: number) {
    // The host's bundled ffmpeg with argv: no console, quoting or code page, so Korean paths work on Windows too.
    const rt = hostSdk.media;
    if (typeof rt?.runFFmpeg === "function") {
      await store.ensure(dir);
      const dur = Math.max(1, duration || 30);
      try {
        for (const argv of [
          ["-v", "error", "-y", "-i", file, "-vf", `fps=16/${dur.toFixed(2)},scale=${sw}:${sh}`, "-frames:v", "16", store.join(dir, "s_%02d.png")],
          ["-v", "error", "-y", "-ss", (dur / 2).toFixed(2), "-i", file, "-frames:v", "1", "-vf", `scale=${W}:${H}`, store.join(dir, "full.png")],
        ]) {
          const r = await rt.runFFmpeg(argv, true);
          if (r && typeof r.exitCode === "number" && r.exitCode !== 0) throw new Error(String(r.stderr || "ffmpeg " + r.exitCode));
        }
      } catch (e: any) {
        throw new Error(S.refsFailed + String(e?.message || e).slice(-300));
      }
      return;
    }
    const T = await tools();
    if (!T.ffmpeg) throw new Error(S.refsFailed + "ffmpeg");
    await store.ensure(dir);
    const F = qa(T.ffmpeg);
    const dur = Math.max(1, duration || 30);
    const cmd =
      `${F} -v error -y -i ${qa(file)} -vf ${qa(`fps=16/${dur.toFixed(2)},scale=${sw}:${sh}`)} -frames:v 16 ${qa(store.join(dir, "s_%02d.png"))}` +
      ` && ${F} -v error -y -ss ${(dur / 2).toFixed(2)} -i ${qa(file)} -frames:v 1 -vf ${qa(`scale=${W}:${H}`)} ${qa(store.join(dir, "full.png"))}`;
    const r = await shell(cmd, "Read frames from a reference short", 240000);
    if (r.exitCode !== 0) throw new Error(S.refsFailed + (r.stderr || r.output).slice(-300));
  }

  async function analyzeRefs() {
    setAError("");
    setAStatus("");
    const links = refsText.split(/\s+/).map((s) => s.trim()).filter((s) => /^https?:\/\//.test(s));
    if (!links.length) return setAError(S.needRefs);
    if (!store.fs) return setAError(S.noFileAccess);
    setABusy(true);
    try {
      const T = await tools();
      const Y = qa(T.ytdlp);
      // 1. Which shorts. A channel link: its most-viewed recent shorts. Short links: those shorts, and when
      // there are fewer than four, more shorts from the same channel that share their look (picked after
      // measuring). The same short pasted twice counts once.
      setAStep(0);
      setAStatus(S.findingShorts);
      const idOf = (u: string) =>
        (u.match(/tiktok\.com\/@[^/]+\/(?:video|photo)\/(\d+)/) || u.match(/youtube\.com\/shorts\/([\w-]{6,})/) || u.match(/[?&]v=([\w-]{6,})/) || u.match(/youtu\.be\/([\w-]{6,})/) || [])[1] || "";
      const isChannel = (u: string) => /youtube\.com\/(@[^/?#]+|channel\/[^/?#]+|c\/[^/?#]+|user\/[^/?#]+)(\/(shorts|videos))?\/?(\?.*)?$/.test(u) || /tiktok\.com\/@[^/?#]+\/?(\?.*)?$/.test(u);
      const unique: string[] = [];
      for (const l of links) {
        const key = idOf(l) || l.replace(/[?#].*$/, "");
        if (!unique.some((u) => (idOf(u) || u.replace(/[?#].*$/, "")) === key)) unique.push(l);
      }
      const seeds = unique.filter((u) => !isChannel(u)).map(idOf).filter(Boolean);
      let cands: any[] = unique.filter((u) => !isChannel(u)).slice(0, 12).map((u) => ({ url: u, title: "", views: null }));
      let others: any[] = [];
      let channel = "";
      let listUrl = "";
      if (unique.some(isChannel)) listUrl = unique.find(isChannel)!.replace(/[?#].*$/, "");
      else if (unique.length < 4) {
        const first = unique[0];
        const tt = first.match(/^(https?:\/\/(?:www\.)?tiktok\.com\/@[^/]+)\//);
        if (tt) listUrl = tt[1];
        else {
          const r0 = await shell(`${Y} --no-warnings --encoding utf-8 --skip-download --no-playlist --print ${qa("SEED\t%(channel_url)s")} ${qa(first)}`, "Find the short's channel", 120000);
          const line = r0.stdout.split(/\r?\n/).find((l: string) => l.startsWith("SEED\t"));
          if (line) listUrl = line.split("\t")[1].trim();
        }
      }
      if (listUrl) {
        if (/youtube\.com\/(@[^/?#]+|channel\/[^/?#]+|c\/[^/?#]+|user\/[^/?#]+)\/?$/.test(listUrl)) listUrl = listUrl.replace(/\/?$/, "/shorts");
        // The listing goes to a file: however long the titles, it never meets the shell's output limit.
        await store.ensure(store.refs);
        const listFile = store.join(store.refs, "listing-" + Date.now().toString(36) + ".txt");
        await shell(
          `${Y} --no-warnings --encoding utf-8 --flat-playlist --playlist-end 60 --print-to-file ${qa("ROW\t%(playlist_title)s\t%(url)s\t%(view_count)s\t%(duration)s\t%(title)s")} ${qa(listFile)} ${qa(listUrl)}`,
          "List the channel's shorts",
          240000
        );
        const text = await store.exists(listFile) ? dec(await store.fs.readFile(listFile)) : "";
        const rows = text
          .split(/\r?\n/)
          .filter((l: string) => l.startsWith("ROW\t"))
          .map((l: string) => {
            const [, list, link, views, dur, ...title] = l.split("\t");
            const n = (v: string) => (/^\d+(\.\d+)?$/.test(v) ? Number(v) : null);
            return { list, url: link, title: title.join("\t"), views: n(views), duration: n(dur) };
          })
          .filter((x: any) => /^https?:\/\//.test(x.url));
        if (!rows.length && !cands.length) throw new Error(S.noShortsFound);
        if (rows.length) {
          channel = String(rows[0].list || "").replace(/\s*-\s*Shorts$/, "").replace(/^NA$/, "");
          const ranked = rows.slice().sort((a: any, b: any) => (b.views ?? -1) - (a.views ?? -1));
          // Pasted shorts first (with their view counts from the listing), then the channel's most viewed.
          const given = cands.map((c) => ranked.find((x: any) => idOf(c.url) && String(x.url).includes(idOf(c.url))) || c);
          const rest = ranked.filter((x: any) => !given.includes(x));
          cands = [...given, ...rest].slice(0, given.length ? 16 : 12);
          others = ranked.slice(-6).filter((x: any) => !cands.includes(x));
          setAStatus(S.foundShorts(Math.min(REF_COUNT, cands.length), rows.length));
        }
      }
      // 2. Download them.
      setAStep(1);
      const job = "a" + Date.now().toString(36);
      const dir = store.join(store.refs, job);
      const got: any[] = [];
      for (let i = 0; i < cands.length; i++) {
        setAStatus(S.refDownloading(i + 1, cands.length));
        try {
          // References are only read for frames, so take the sharpest picture in any codec.
          const d = await download(cands[i].url, dir, "bv*[height<=1920]+ba/b[height<=1920]/b", () => {});
          got.push({ ...cands[i], ...d, views: d.views ?? cands[i].views, title: d.title || cands[i].title });
        } catch (e) {}
      }
      if (got.length < 2) throw new Error(S.tooFewRefs);
      // 3. Frames, grouping by look, and the layout measurement.
      setAStep(2);
      setAStatus(S.measuring);
      const ratios = got.map((g) => (g.w && g.h ? g.w / g.h : 9 / 16));
      const ratio = median(ratios);
      const shape = Object.keys(SHAPES).sort((a, b) => Math.abs(SHAPES[a][0] / SHAPES[a][1] - ratio) - Math.abs(SHAPES[b][0] / SHAPES[b][1] - ratio))[0];
      const [W, H] = SHAPES[shape];
      const sw = 216;
      const sh = Math.round((216 * H) / W / 2) * 2;
      const strips: Frame[][] = [];
      const kept: any[] = [];
      for (let i = 0; i < got.length; i++) {
        const fd = store.join(dir, "f" + i);
        try {
          await frames(got[i].file, fd, got[i].duration, sw, sh, W, H);
          const names = (await store.fs.readdir(fd)).filter((n: string) => /^s_\d+\.png$/.test(n)).sort();
          const fr: Frame[] = [];
          for (const n of names) fr.push(await loadFrame(store.fs, store.join(fd, n), sw, sh));
          if (fr.length >= 4) {
            strips.push(fr);
            kept.push({ ...got[i], dir: fd });
          }
        } catch (e) {}
      }
      if (strips.length < 2) throw new Error(S.tooFewRefs);
      const groups = groupByLook(strips);
      // With pasted shorts, use the group that holds most of them; otherwise the largest group.
      const isSeed = (i: number) => seeds.some((sd) => kept[i].id === sd || String(kept[i].url).includes(sd));
      const mine = seeds.length ? groups.slice().sort((g1, g2) => g2.filter(isSeed).length - g1.filter(isSeed).length || g2.length - g1.length)[0] : null;
      const best = mine && mine.length >= 2 ? mine : groups[0].length >= 2 ? groups[0] : strips.map((_, i) => i);
      const ix = best.slice(0, REF_COUNT);
      const refs = ix.map((i) => kept[i]);
      const m = measureLayout(ix.map((i) => strips[i]));
      const k = W / m.w;
      const sc = (b: any) => ({ x: Math.round(b.x * k), y: Math.round(b.y * k), w: Math.round(b.w * k), h: Math.round(b.h * k) });
      const video = sc(m.video);
      const fulls: Frame[] = [];
      for (const r of refs) fulls.push(await loadFrame(store.fs, store.join(r.dir, "full.png"), W, H));
      const lines = textLines(fulls, m.texts.map(sc));
      // Background: the template's own picture, or one colour when it is plain.
      let background: any = { mode: "none", color: "#000000", image: "", imageName: "", dim: 0 };
      let bgCanvas: HTMLCanvasElement | null = null;
      if (!m.fullScreen) {
        if (m.uniform) background = { ...background, mode: "color", color: m.bg };
        else {
          const bandBoxes = m.bands.map((b: number[]) => ({ x: 0, y: b[0] * k, w: W, h: (b[1] - b[0] + 1) * k }));
          bgCanvas = backgroundImage(fulls, m.bg, video, [...lines, ...bandBoxes]);
          background = { mode: "image", color: m.bg, image: await bitmapToDataUrl(await createImageBitmap(bgCanvas), "background", W, H), imageName: channel || "reference shorts", dim: 0 };
        }
      }
      // Marks that never change over the video (a logo, a fixed label) become picture layers.
      const images: any[] = [];
      for (const fb of m.fixed.map(sc).slice(0, 3)) {
        const c = document.createElement("canvas");
        c.width = fb.w;
        c.height = fb.h;
        const t = document.createElement("canvas");
        t.width = W;
        t.height = H;
        t.getContext("2d")!.putImageData(new ImageData(new Uint8ClampedArray(fulls[0].d), W, H), 0, 0);
        c.getContext("2d")!.drawImage(t, fb.x, fb.y, fb.w, fb.h, 0, 0, fb.w, fb.h);
        try {
          images.push({ id: "p" + images.length, role: "picture", ...fb, image: await bitmapToDataUrl(await createImageBitmap(c), "picture", W, H), name: channel || "reference" });
        } catch (e) {}
      }
      // 4. The AI reads roles and looks from the pictures.
      setAStep(3);
      setAStatus(S.readingStyle);
      const labels = [{ label: "V", ...video }, ...lines.map((l: any, i: number) => ({ label: "T" + (i + 1), ...l }))];
      const pics = [{ dataUrl: sheet(fulls, labels, Math.min(3, fulls.length), 300), name: "frames.jpg" }];
      if (bgCanvas) {
        const small = document.createElement("canvas");
        small.width = 540;
        small.height = Math.round((540 * H) / W);
        small.getContext("2d")!.drawImage(bgCanvas, 0, 0, small.width, small.height);
        pics.push({ dataUrl: small.toDataURL("image/jpeg", 0.8), name: "background.jpg" });
      }
      const measured = lines.map((l: any, i: number) => ({ box: "T" + (i + 1), x: l.x, y: l.y, w: l.w, h: l.h, color: l.color, letterHeight: l.inkHeight, boxColor: l.box }));
      const st = extractJson((await sdk.askAI({ prompt: stylePrompt({ W, H, measured }, refs), images: pics.slice(0, AI_MAX_IMAGES), timeoutMs: 300000 })).text, S);
      // 5. What works on this channel.
      setAStep(4);
      setAStatus(S.learning);
      const learn = extractJson(
        (await sdk.askAI({ prompt: learnPrompt(refs, others, st.headlines || [], lang, refs.map((r) => r.duration).filter(Boolean)), timeoutMs: 300000 })).text,
        S
      );
      // Keep the AI's answers and the measurements next to the downloads, for checking a template later.
      try {
        await store.fs.writeFile(store.join(dir, "analysis.json"), enc(JSON.stringify({ measured, layout: { video, bands: m.bands, fullScreen: m.fullScreen }, style: st, learn }, null, 1)));
      } catch (e) {}
      // Assemble the template from the measurements and the AI's reading. The AI may name a box "T1" or
      // "1" and a role "headline", "title" or "headline 1"; all are read the same way.
      const norm = (r: any) => {
        const v = String(r || "").toLowerCase().replace(/[\s_-]/g, "");
        if (/^(headline|headline1|title|title1|main|mainheadline|line1)$/.test(v)) return "headline1";
        if (/^(headline2|title2|subheadline|subtitle|subject|line2|secondheadline)$/.test(v)) return "headline2";
        if (/caption/.test(v)) return "caption";
        return v ? "ignore" : "";
      };
      const roleOf = (label: string) => {
        const lab = (t: any) => String(t.label ?? (typeof t.box === "string" ? t.box : "") ?? t.id ?? "").trim().replace(/^t/i, "T").replace(/^(\d+)$/, "T$1");
        const list = st.texts || [];
        // By label; failing that, the answer in the same order as the measured boxes.
        const a = list.find((t: any) => lab(t) === label) || (list.length === lines.length ? list[Number(label.slice(1)) - 1] : null) || {};
        return { ...a, role: norm(a.role) };
      };
      // Two boxes both called headline1: the lower one is headline2.
      const roles = lines.map((_: any, i: number) => roleOf("T" + (i + 1)).role);
      const firstH1 = roles.indexOf("headline1");
      roles.forEach((r: string, i: number) => {
        if (r === "headline1" && i !== firstH1 && !roles.includes("headline2")) roles[i] = "headline2";
      });
      // No headline named at all: the per-short text lines outside the video, top to bottom.
      if (!roles.some((r: string) => r === "headline1" || r === "headline2")) {
        const outside = lines.map((l: any, i: number) => ({ l, i })).filter(({ l }: any) => roles[lines.indexOf(l)] !== "caption" && (l.y + l.h <= video.y + 10 || l.y >= video.y + video.h - 10 || m.fullScreen));
        outside.slice(0, 2).forEach(({ i }: any, k: number) => (roles[i] = k === 0 ? "headline1" : "headline2"));
      }
      const texts: any[] = [];
      lines.forEach((l: any, i: number) => {
        const a = { ...roleOf("T" + (i + 1)), role: roles[i] };
        if (a.role !== "headline1" && a.role !== "headline2") return;
        texts.push({
          id: a.role, role: a.role, text: "", x: l.x, y: l.y, w: l.w, h: l.h, align: ["left", "center", "right"].includes(a.align) ? a.align : "center", font: "",
          size: Math.round(Number(a.size) > 10 ? Number(a.size) : l.inkHeight / 0.8), weight: Number(a.weight) || 800, color: l.color || a.color || "#FFFFFF",
          lineHeight: 1.18, tracking: -1, italic: !!a.italic, shadow: !!a.shadow,
          stroke: { on: !!a.outline?.on, color: a.outline?.color || "#000000", width: Number(a.outline?.width) || 8 },
          box: { on: !!(l.box || a.textBox?.on || a.box?.on), color: l.box || a.textBox?.color || a.box?.color || "#000000", padX: 22, padY: 6, radius: 0, gap: 10 },
        });
      });
      if (st.video && Number(st.video.w) > 100 && Number(st.video.h) > 100) Object.assign(video, { x: Math.round(st.video.x), y: Math.round(st.video.y), w: Math.round(st.video.w), h: Math.round(st.video.h) });
      const band = m.bands.length ? m.bands.map((b: number[]) => [b[0] * k, b[1] * k]).sort((a: number[], b: number[]) => b[1] - b[0] - (a[1] - a[0]))[0] : null;
      const C = st.captions || {};
      const captions = {
        on: C.on !== false && (C.on === true || !!band),
        style: ["box", "outline", "shadow", "plain"].includes(C.style) ? C.style : "plain",
        y: Math.round(Number(C.y) > 0 ? Number(C.y) : band ? (band[0] + band[1]) / 2 : H * 0.72),
        fontSize: Math.round(Number(C.size) || 60),
        fontWeight: Number(C.weight) || 700,
        color: C.color || "#FFFFFF",
        boxColor: C.boxColor || "#000000A6",
        font: "",
        lineMax: H > W ? 16 : 28,
      };
      const still = (() => {
        const c = document.createElement("canvas");
        c.width = Math.round(video.w / 3);
        c.height = Math.round(video.h / 3);
        const t = document.createElement("canvas");
        t.width = W;
        t.height = H;
        t.getContext("2d")!.putImageData(new ImageData(new Uint8ClampedArray(fulls[0].d), W, H), 0, 0);
        c.getContext("2d")!.drawImage(t, video.x, video.y, video.w, video.h, 0, 0, c.width, c.height);
        return c.toDataURL("image/jpeg", 0.7);
      })();
      const pickText = (v: any, d: string) => (typeof v === "string" && v.trim() ? v.trim() : d);
      const D = BUILTIN_TEMPLATES[0].prompt;
      const id = "t" + Date.now().toString(36);
      const tpl = {
        id,
        version: 2,
        created: new Date().toISOString(),
        name: refsName.trim() || pickText(learn.name, S.resultName(channel || "reference")),
        names: {},
        descriptions: { [lang]: pickText(st.description, "") },
        layout: { width: W, height: H, background, video: { ...video, fit: "cover", zoom: 1, focusX: 0.5, focusY: 0.5, border: { on: false, color: "#FFFFFF", width: 4 } }, texts, images },
        captions,
        editing: { removeFillers: true, removeSilences: true },
        prompt: {
          role: pickText(learn.role, D.role),
          format: pickText(learn.format, D.format),
          good: pickText(learn.good, D.good),
          bad: pickText(learn.bad, D.bad),
          lengthGuide: pickText(learn.lengthGuide, D.lengthGuide),
          countGuide: pickText(learn.countGuide, D.countGuide),
          rules: pickText(learn.rules, D.rules),
          headline: pickText(learn.headline, D.headline),
        },
        source: { references: refs.map((r) => r.url), channel, still },
      };
      await store.put("templates", id, tpl);
      await loadTemplates();
      setTplSel(id);
      setTplSub("layout");
      setRefsView(false);
      setAStatus("");
      setAStep(-1);
      setTplEdit(null);
      setRefsText("");
      setRefsName("");
      setAError("");
      setError("");
      setStatus("");
      setTab("templates");
      setInfo(null);
      setAStatus(S.analyzed);
    } catch (e: any) {
      setAError(String(e?.message || e));
    } finally {
      setABusy(false);
    }
  }

  // ---- Screens ----
  const videoOptions = resources.filter((r) => r.sec >= 60).map((r) => ({ value: r.id, label: `${r.name}${r.analyzed ? "" : " · " + S.notAnalyzedTag}` }));
  const make = !projectId ? (
    <ui.Message>{S.noProject}</ui.Message>
  ) : (
    <ui.Stack gap={16}>
      {jobs.length > 0 && !busy && (
        <ui.Section title={S.saved}>
          {jobs.slice(0, 3).map((j) => (
            <ui.Stack key={j.id} gap={4}>
              <p>
                {(j.title || j.url || j.pick || "").slice(0, 60)} · {S.stage(j)}
              </p>
              <ui.Row gap={8}>
                <ui.Button variant="secondary" onClick={() => run(j)}>
                  {S.resume}
                </ui.Button>
                <ui.Button variant="ghost" onClick={() => dismissJob(j)}>
                  {S.dismiss}
                </ui.Button>
              </ui.Row>
            </ui.Stack>
          ))}
        </ui.Section>
      )}
      <ui.Section title={S.source}>
        <ui.Segmented
          label={S.source}
          value={mode}
          onChange={setMode}
          options={[
            { value: "link", label: S.fromLink },
            { value: "project", label: S.fromProject },
          ]}
          disabled={busy}
        />
        {mode === "link" ? (
          <ui.TextField label={S.url} value={url} onChange={setUrl} placeholder={S.urlPh} disabled={busy} />
        ) : (
          <ui.Stack gap={4}>
            <ui.Select label={S.pick} value={pick} onChange={setPick} options={videoOptions} placeholder={S.pickPh} disabled={busy} />
            {pick && <small>{resources.find((r) => r.id === pick)?.name}</small>}
          </ui.Stack>
        )}
      </ui.Section>
      <ui.Section title={S.template}>
        <ui.Select label={S.template} value={tplId || null} onChange={setTplId} options={templates.map((t) => ({ value: t.id, label: nameOf(t, lang) }))} disabled={busy} />
        {templates.find((t) => t.id === tplId) && <LayerPreview t={templates.find((t) => t.id === tplId)} S={S} maxWidth={150} still={templates.find((t) => t.id === tplId)?.source?.still || ""} />}
        <ui.Segmented
          label={S.count}
          value={countMode}
          onChange={setCountMode}
          options={[
            { value: "auto", label: S.countAuto },
            { value: "manual", label: S.countManual },
          ]}
          disabled={busy}
        />
        {countMode === "manual" && <ui.NumberField label={S.howMany} value={count} onChange={(v: number) => setCount(Math.max(1, Math.min(12, Math.round(v))))} min={1} max={12} step={1} disabled={busy} />}
        <ui.TextField label={S.note} value={note} onChange={setNote} placeholder={S.notePh} multiline disabled={busy} />
      </ui.Section>
      <ui.Actions>
        <ui.Button variant="primary" busy={busy} busyLabel={S.making} onClick={() => run()}>
          {S.make}
        </ui.Button>
      </ui.Actions>
      {step >= 0 && <ui.Progress steps={S.steps} current={step} />}
      {status && <ui.Message tone={step >= 4 && !error ? "success" : "muted"}>{status}</ui.Message>}
      {error && <ui.Message tone="error">{error}</ui.Message>}
      {info && info.recommended != null && info.countReason && <p>{S.recommended(info.recommended, info.countReason)}</p>}
      {drafts.length > 0 && (
        <ui.Stack gap={8}>
          {drafts.map((d, i) => (
            <ui.Row key={i} gap={8}>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div>{d.headline1}</div>
                <small>{d.error ? d.error : `${d.headline2}${d.seconds ? ` · ${d.seconds}s` : ""}`}</small>
              </div>
              {d.draftId && (
                <ui.Button variant="ghost" onClick={() => openDraft(d.draftId)}>
                  {S.open}
                </ui.Button>
              )}
            </ui.Row>
          ))}
        </ui.Stack>
      )}
    </ui.Stack>
  );

  const refsForm = (
    <ui.Stack gap={16}>
      <ui.Section title={S.refsTitle}>
        <small>{S.refsHint}</small>
        <ui.TextField label={S.refsLinks} value={refsText} onChange={setRefsText} placeholder={S.refsPh} multiline disabled={aBusy} />
        <ui.TextField label={S.refsName} value={refsName} onChange={setRefsName} disabled={aBusy} />
      </ui.Section>
      <ui.Actions>
        <ui.Button variant="ghost" onClick={() => setRefsView(false)} disabled={aBusy}>
          {S.back}
        </ui.Button>
        <ui.Button variant="primary" busy={aBusy} busyLabel={S.analyzing} onClick={analyzeRefs}>
          {S.analyze}
        </ui.Button>
      </ui.Actions>
      {aStep >= 0 && <ui.Progress steps={S.aSteps} current={aStep} />}
      {aStatus && <ui.Message tone="muted">{aStatus}</ui.Message>}
      {aError && <ui.Message tone="error">{aError}</ui.Message>}
    </ui.Stack>
  );

  return (
    <ui.Tabs
      value={tab}
      onChange={setTab}
      tabs={[
        { value: "make", label: S.tabMake, content: make },
        {
          value: "templates",
          label: S.tabTemplates,
          content: refsView ? (
            refsForm
          ) : (
            <ui.Stack gap={8}>
              {aStatus && !aBusy && <ui.Message tone="success">{aStatus}</ui.Message>}
              <TemplateEditor
                ui={ui}
                S={S}
                lang={lang}
                templates={templates}
                store={store}
                onAnalyze={() => {
                  setAStatus("");
                  setRefsView(true);
                }}
                state={{ selId: tplSel, setSelId: setTplSel, edit: tplEdit, setEdit: setTplEdit, baseKey: tplBase, setBaseKey: setTplBase, sub: tplSub, setSub: setTplSub }}
                onChanged={loadTemplates}
              />
            </ui.Stack>
          ),
        },
      ]}
    />
  );
}


// Only read-only media queries use this: keep every row without exceeding run_script's response limit.
async function readMediaPages(sdk, args) {
  let result, total;
  for (let offset = 0; ; offset += 32) {
    const script = `const value=await(async()=>{${args.script}\n})();const array=Array.isArray(value);const data=array?{rows:value}:value;const page={};let total=0;for(const key of Object.keys(data)){const rows=data[key];page[key]=Array.isArray(rows)?rows.slice(${offset},${offset + 32}):rows;if(Array.isArray(rows))total=Math.max(total,rows.length);}return {array,page,total};`;
    const reply = await sdk.runScript({ ...args, script, allowCommit: false });
    if (reply.isError || !reply.result?.page) throw new Error(reply.output || 'Could not read the Project media.');
    const batch = reply.result;
    if (total !== undefined && total !== batch.total) throw new Error('Project media changed while loading. Try again.');
    total = batch.total;
    if (offset === 0) result = batch.page;
    else for (const key of Object.keys(batch.page)) if (Array.isArray(batch.page[key])) result[key].push(...batch.page[key]);
    if (offset + 32 >= total) return { ...reply, result: batch.array ? result.rows : result };
  }
}

let hostSdk: any = null;
function hostUseSdk(sdk: any) { hostSdk = panelLocalClient(sdk); if (!hostSdk?.files || !hostSdk?.media || !hostSdk?.environment) throw new Error("Update Selects to use this plugin."); }

// local-sdk:start
/** Pure host-platform path operations; no filesystem or renderer globals. */
function panelLocalPaths(platform: string) {
  const windows = platform === "win32";
  const slash = (path: string) => {
    if (typeof path !== "string")
      throw new TypeError("A path must be a string.");
    return windows ? path.replace(/\\/g, "/") : path;
  };
  const rootOf = (path: string) => {
    if (windows) {
      const unc = path.match(/^\/\/[^/]+\/[^/]+\/?/);
      if (unc) return unc[0].replace(/\/?$/, "/");
      const drive = path.match(/^[a-z]:\/?/i);
      if (drive) return drive[0];
    }
    return path.startsWith("/") ? "/" : "";
  };
  const native = (value: string) =>
    windows ? value.replace(/\//g, "\\") : value;
  const normalize = (value: string) => {
    const path = slash(value),
      root = rootOf(path),
      absolute = root.endsWith("/");
    const segments: string[] = [];
    for (const segment of path
      .slice(Math.min(root.length, path.length))
      .split("/")) {
      if (!segment || segment === ".") continue;
      if (segment === ".." && segments.length && segments.at(-1) !== "..")
        segments.pop();
      else if (segment !== ".." || !absolute) segments.push(segment);
    }
    let result = root + segments.join("/");
    if (!result || (windows && /^[a-z]:$/i.test(result))) result += ".";
    if (path.endsWith("/") && !result.endsWith("/")) result += "/";
    return native(result);
  };
  const basename = (value: string, extension?: string) => {
    const path = slash(value).replace(/\/+$/, "");
    const withoutDrive = windows ? path.replace(/^[a-z]:/i, "") : path;
    const name = withoutDrive.slice(withoutDrive.lastIndexOf("/") + 1);
    return extension && name.endsWith(extension)
      ? name.slice(0, -extension.length)
      : name;
  };
  return {
    normalize,
    join: (...paths: string[]) => {
      const parts = paths.map(slash).filter(Boolean);
      let joined = parts.join("/");
      if (windows && !/^\/\/[^/]/.test(parts[0] || ""))
        joined = joined.replace(/^\/{2,}/, "/");
      return normalize(joined);
    },
    dirname(value: string) {
      const path = slash(value),
        root = rootOf(path);
      const end = path.replace(/\/+$/, "").lastIndexOf("/");
      if (end < root.length) return value.slice(0, root.length) || ".";
      return value.slice(0, end);
    },
    basename,
    extname(value: string) {
      const name = basename(value),
        dot = name.lastIndexOf(".");
      return dot <= 0 || name === ".." ? "" : name.slice(dot);
    },
    isAbsolute: (value: string) => rootOf(slash(value)).endsWith("/"),
  };
}


/** Plugin-private composition of canonical SDK methods, not a public SDK surface. */
async function createPanelLocalClient(sdk: any) {
  const run = async (method: string, args: unknown[], write = false) => {
    // method names below are fixed implementation constants; values always use JSON encoding.
    // Direct arguments keep object literals contextually typed by the SDK signature.
    const response = await sdk.runScript({
      summary: "Use local media workspace",
      allowCommit: write,
      script: "return await selects." + method + "(" + JSON.stringify(args).slice(1, -1) + ");",
    });
    if (response.isError) throw new Error(response.output || "Local SDK operation failed.");
    // A clipped report has no result. Every read returning data rejects that case below.
    return response.result;
  };
  const environment = await run("files.environment", []);
  if (!environment || typeof environment.platform !== "string" || !environment.homedir)
    throw new Error("Update Selects to use this plugin's local media workspace.");
  const paths = panelLocalPaths(environment.platform);
  const CHUNK_BYTES = 48 * 1024;
  const readRange = async (path: string, offset: number, length: number) => {
    const parts: Uint8Array[] = [];
    let total = 0;
    while (total < length) {
      const result = await run("files.readRange", [{ path, offset: offset + total, length: Math.min(CHUNK_BYTES, length - total) }]);
      if (!result || typeof result.base64 !== "string" || !Number.isInteger(result.bytesRead)) throw new Error("The file read returned an incomplete result.");
      const bytes = Uint8Array.from(atob(result.base64), (character) => character.charCodeAt(0));
      if (bytes.length !== result.bytesRead) throw new Error("The file read returned invalid bytes.");
      parts.push(bytes); total += bytes.length;
      if (bytes.length < Math.min(CHUNK_BYTES, length - (total - bytes.length))) break;
    }
    const output = new Uint8Array(total);
    let position = 0;
    for (const bytes of parts) { output.set(bytes, position); position += bytes.length; }
    return output;
  };
  const files = {
    ...paths,
    homedir: () => environment.homedir,
    getOrCreateTmpDirPath: async () => environment.tempDirectory,
    exists: (path: string) => run("files.exists", [path]),
    stat: (path: string) => run("files.stat", [path]),
    readdir: (path: string) => run("files.readdir", [path]),
    readRange,
    async readFile(path: string, encoding?: string) {
      const stat = await run("files.stat", [path]);
      if (!stat || !Number.isSafeInteger(stat.size) || stat.size < 0) throw new Error("The file is unavailable.");
      const bytes = await readRange(path, 0, stat.size);
      if (bytes.length !== stat.size) throw new Error("The file changed while it was being read.");
      if (encoding !== undefined && encoding !== "utf8") throw new Error("Only utf8 text encoding is supported.");
      return encoding === "utf8" ? new TextDecoder().decode(bytes) : bytes;
    },
    async writeFile(path: string, data: string | Uint8Array, options?: string | { encoding?: string; flag?: "w" | "a" | "wx" }) {
      const encoding = typeof options === "string" ? options : options?.encoding;
      const flag = typeof options === "object" ? options.flag : undefined;
      if (flag !== undefined && !["w", "a", "wx"].includes(flag)) throw new Error("Unsupported file write flag.");
      if (encoding !== undefined && encoding !== "utf8") throw new Error("Only utf8 text encoding is supported.");
      const bytes = typeof data === "string" ? new TextEncoder().encode(data) : new Uint8Array(data);
      if ((flag === "a" || flag === "wx") && bytes.length > CHUNK_BYTES) throw new Error("Atomic append and exclusive creation are limited to 48 KiB.");
      // Each complete replacement has its own sibling file. Other panels cannot
      // overwrite one of its chunks before the final atomic rename publishes it.
      const replacement = flag !== "a" && flag !== "wx";
      const destination = replacement ? path + ".tmp-" + crypto.randomUUID() : path;
      let published = false;
      try {
        for (let offset = 0; offset < bytes.length || offset === 0; offset += CHUNK_BYTES) {
          const chunk = bytes.subarray(offset, offset + CHUNK_BYTES);
          let binary = "";
          for (const byte of chunk) binary += String.fromCharCode(byte);
          const mode = offset === 0 ? (flag === "a" ? "append" : "exclusive") : undefined;
          const result = await run("files.writeChunk", [{ path: destination, offset, base64: btoa(binary), ...(mode ? { mode } : {}) }], true);
          if (result?.bytesWritten !== chunk.length) throw new Error("The file write returned an incomplete result. Check the file before retrying.");
        }
        if (replacement) await run("files.rename", [destination, path], true);
        published = true;
      } finally {
        if (replacement && !published) await run("files.remove", [destination, { force: true }], true).catch(() => {});
      }
    },
    async compareAndReplace(path: string, expectedText: string | null, text: string) {
      const encode = (value: string) => {
        const bytes = new TextEncoder().encode(value);
        if (bytes.length > CHUNK_BYTES) throw new Error("Atomic file values are limited to 48 KiB.");
        let binary = "";
        for (const byte of bytes) binary += String.fromCharCode(byte);
        return btoa(binary);
      };
      const result = await run("files.compareAndReplace", [{path, expectedBase64: expectedText === null ? null : encode(expectedText), base64: encode(text)}], true);
      if (typeof result?.replaced !== "boolean") throw new Error("The atomic file update returned an incomplete result. Read the file before retrying.");
      return result.replaced;
    },
    mkdir: (path: string, options?: { recursive?: boolean }) => run("files.mkdir", [path, options ?? {}], true),
    rm: (path: string, options?: { recursive?: boolean; force?: boolean }) => run("files.remove", [path, options ?? {}], true),
    removeFile: ({ filePath }: { filePath: string }) => run("files.remove", [filePath, { force: true }], true),
    rename: (from: string, to: string) => run("files.rename", [from, to], true),
    copyFile: (from: string, to: string) => run("files.copy", [from, to], true),
    downloadFile: (url: string, path: string) => run("files.download", [url, path], true),
    pathToLocalURL: (path: string) => run("files.localUrl", [path]),
    localURLToPath: (url: string) => run("files.pathFromLocalUrl", [url]),
  };
  const activeJobs = new Set<string>();
  let disposed = false;
  const cancel = async (jobId: string) => {
    const response = await sdk.runScript({ summary: "Cancel local media processing", allowCommit: true, script: "await selects.media.job(" + JSON.stringify(jobId) + ").cancel();" });
    if (response.isError) throw new Error(response.output || "Media cancellation failed.");
  };
  const process = async (executable: "FFmpeg" | "FFprobe", args: string[], _withoutLog?: boolean, signal?: AbortSignal, onStdout?: (text: string) => void, onStderr?: (text: string) => void) => {
    if (disposed || signal?.aborted) throw new DOMException("Aborted", "AbortError");
    const started = await run("media.start" + executable, [{ args }], true);
    if (!started?.jobId) throw new Error("The media process did not return a job id.");
    const jobId = started.jobId;
    activeJobs.add(jobId);
    let cancellation: Promise<void> | null = null;
    const abort = () => { cancellation ??= cancel(jobId); void cancellation.catch(() => {}); };
    signal?.addEventListener("abort", abort, { once: true });
    if (disposed || signal?.aborted) abort();
    let cursor = 0, stdout = "", stderr = "";
    try {
      while (true) {
        if (cancellation) await cancellation;
        const status = await sdk.call("getLocalMediaJobStatus", jobId, { cursor });
        if (!status || !Array.isArray(status.events)) throw new Error("Media status is unavailable.");
        if (status.truncated) throw new Error("Media output was truncated; no incomplete result was accepted.");
        for (const event of status.events) {
          if (event.stream === "stdout") { stdout += event.text; onStdout?.(event.text); }
          else { stderr += event.text; onStderr?.(event.text); }
        }
        cursor = status.nextCursor;
        if (status.state !== "running" && status.events.length === 0) {
          if (status.state === "cancelled" || signal?.aborted) throw new DOMException("Aborted", "AbortError");
          if (status.state === "failed") throw new Error(status.error || stderr || "Media processing failed.");
          return { stdout, stderr };
        }
        if (status.state === "running") await new Promise((resolve) => setTimeout(resolve, 150));
      }
    } catch (error) {
      await cancel(jobId).catch(() => {});
      throw error;
    } finally {
      signal?.removeEventListener("abort", abort);
      activeJobs.delete(jobId);
    }
  };
  return {
    files,
    environment,
    media: {
      runFFmpeg: (args: string[], quiet?: boolean, signal?: AbortSignal, stdout?: (text: string) => void, stderr?: (text: string) => void) => process("FFmpeg", args, quiet, signal, stdout, stderr),
      runFFprobe: (args: string[], quiet?: boolean, signal?: AbortSignal) => process("FFprobe", args, quiet, signal),
    },
    dialogs: {
      pickFilePath: (filters?: Array<{ name: string; extensions: string[] }>) => run("editor.pickFile", [{ filters }]),
      pickDirectoryPath: () => run("editor.pickDirectory", []),
      pickSavePath: (defaultPath: string) => run("editor.pickSavePath", [{ defaultPath }]),
    },
    dispose() { disposed = true; for (const jobId of activeJobs) void cancel(jobId).catch(() => {}); },
  };
}

const panelLocalClients = new WeakMap<object, any>();
function panelLocalClient(sdk: any): any {
  const client = panelLocalClients.get(sdk);
  if (!client) throw new Error("Local SDK has not initialized.");
  return client;
}
function withPanelLocalClient(Component: any) {
  return function LocalSdkPanel(props: any) {
    const [state, setState] = React.useState<any>(null);
    React.useEffect(() => {
      let active = true;
      let client: any;
      createPanelLocalClient(props.sdk).then(value => {
        client = {...props.sdk, ...value};
        if (!active) { value.dispose(); return; }
        panelLocalClients.set(props.sdk, client);
        setState({sdk: props.sdk});
      }).catch(error => { if (active) setState({error: String(error?.message || error)}); });
      return () => {
        active = false;
        if (client) {
          if (panelLocalClients.get(props.sdk) === client) panelLocalClients.delete(props.sdk);
          client.dispose();
        }
      };
    }, [props.sdk]);
    if (state?.error) return React.createElement("div", {role: "alert"}, state.error);
    if (state?.sdk !== props.sdk) return React.createElement("div", {role: "status"}, "Connecting to Selects…");
    return React.createElement(Component, props);
  };
}

export default withPanelLocalClient(Panel);
// local-sdk:end
